export const MARKDOWN_BUNDLE: Record<string, string> = {
  "en/about/code-of-conduct": "# Code of Conduct\n\nNucleify follows the [Contributor Covenant Code of Conduct 2.1](https://www.contributor-covenant.org/version/2/1/code_of_conduct/).\n\n---\n\n## Our Pledge\n\nWe pledge to make participation in our community a harassment-free experience for everyone, regardless of age, body size, visible or invisible disability, ethnicity, sex characteristics, gender identity and expression, level of experience, education, socio-economic status, nationality, personal appearance, race, caste, color, religion, or sexual identity and orientation.\n\nWe pledge to act and interact in ways that contribute to an open, welcoming, diverse, inclusive, and healthy community.\n\n---\n\n## Our Standards\n\n### Positive Behavior\n\n- Demonstrating empathy and kindness\n- Being respectful of differing opinions\n- Giving and gracefully accepting constructive feedback\n- Accepting responsibility and apologizing for mistakes\n- Focusing on what's best for the community\n\n### Unacceptable Behavior\n\n- Sexualized language or imagery\n- Trolling, insults, or derogatory comments\n- Public or private harassment\n- Publishing others' private information\n- Other inappropriate professional conduct\n\n---\n\n## Enforcement\n\nCommunity leaders will follow these guidelines:\n\n### 1. Correction\n\n**Impact**: Inappropriate language or unprofessional behavior.\n\n**Consequence**: Private written warning with explanation.\n\n### 2. Warning\n\n**Impact**: Violation through single incident or series of actions.\n\n**Consequence**: Warning with consequences for continued behavior. No interaction with involved parties for a specified period.\n\n### 3. Temporary Ban\n\n**Impact**: Serious violation, including sustained inappropriate behavior.\n\n**Consequence**: Temporary ban from community interaction.\n\n### 4. Permanent Ban\n\n**Impact**: Pattern of violations, harassment, or aggression.\n\n**Consequence**: Permanent ban from the community.\n\n---\n\n## Reporting\n\nReport issues to: **nucleify@gmail.com**\n\nAll complaints will be reviewed promptly and fairly. Community leaders are obligated to respect the privacy and security of reporters.\n\n---\n\n## Scope\n\nThis Code of Conduct applies within all community spaces and when representing the community in public spaces (official email, social media, events).\n\n---\n\n## Attribution\n\nAdapted from the [Contributor Covenant](https://www.contributor-covenant.org), version 2.1.\n\nCommunity Impact Guidelines inspired by [Mozilla's code of conduct enforcement ladder](https://github.com/mozilla/diversity).\n\n\n",
  "en/about/coding-standards": "# Coding Standards\n\nStandards for code, structure, and naming in Nucleify. Following these ensures readable, consistent, and maintainable code.\n\n---\n\n## Project Structure\n\n```txt\nroot/\n├── modules/                # Self-contained feature modules (supabase/, atomic/)\n├── nuxt/                   # Nuxt frontend\n├── next/                   # Next.js frontend (optional)\n├── supabase/               # Merged SQL temp, local Supabase config\n├── .config/                # Nuxt/Next/tooling configuration\n└── vitests/                # Global frontend tests\n```\n\n---\n\n## Module Structure\n\n```txt\nmodules/<module_name>/\n├── supabase/               # Migrations, seeders, API handlers\n├── atomic/                 # UI (Vue/React/TS/SCSS)\n├── vitests/                # Frontend tests (Vitest)\n├── config.json             # Module metadata\n├── index.ts                # Barrel export\n├── <module_name>.ts        # Vue registration\n├── <module_name>.react.ts  # React registration (optional)\n└── README.md\n```\n\n---\n\n## Naming Conventions\n\n### Backend (Supabase)\n\n| Type | Convention | Example |\n|------|------------|---------|\n| Module folders | `snake_case` | `nuc_users`, `nuc_entities` |\n| SQL migrations | Timestamp prefix | `20260501000000_nuc_users.sql` |\n| API handlers | `snake_case` | `handle.ts` in `supabase/api/` |\n| API routes | `kebab-case` URLs | `/api/user-profile` |\n\n### Frontend (Nuxt/Vue/TypeScript)\n\n| Type | Convention | Example |\n|------|------------|---------|\n| Vue components | `kebab-case` folders | `input-text/index.vue` |\n| TypeScript files | `snake_case` | `use_auth.ts` |\n| Type definitions | `PascalCase` | `UserProps`, `ButtonEmits` |\n| Composables | `use` prefix | `useAuth.ts` |\n| Constants | `SCREAMING_SNAKE_CASE` | `API_BASE_URL` |\n| Entry points | `index.ts` / `index.vue` | Component main file |\n\n---\n\n## Atomic Design Hierarchy\n\n1. **Boson** – Utility functions, helpers\n2. **Atom** – Basic UI elements (Button, Input, Icon)\n3. **Molecule** – Combined atoms (FloatLabel, Anchor)\n4. **Organism** – Complex components (DataTable, Dialog)\n5. **Template** – Page layouts (DashboardLayout)\n\n### Component Structure\n\n```txt\n<component>/\n├── index.vue               # Main component\n├── index.ts                # Exports\n├── _index.scss             # Styles (optional)\n└── types/\n    ├── index.ts\n    ├── interfaces.ts\n    └── variables.ts\n```\n\n---\n\n## Coding Rules\n\n### General\n\n- Prefer **readability** over cleverness\n- Follow **KISS** – Keep It Simple\n- Follow **DRY** – Don't Repeat Yourself\n- Comment only when intent is unclear\n- Remove unused code\n- Keep functions small and focused\n\n### TypeScript\n\n```typescript\n// ✅ Good - explicit types\ninterface UserData {\n  id: number\n  name: string\n  email: string\n}\n\nfunction getUser(id: number): UserData {\n  // ...\n}\n\n// ❌ Bad - avoid any\nfunction getUser(id: any): any {\n  // ...\n}\n```\n\n### API handlers (TypeScript)\n\n```typescript\n// ✅ Good - typed handler result\nexport async function handle(ctx: ApiContext): Promise<ApiHandlerResult> {\n  const crud = await trySimpleCrud(ctx)\n  if (crud.handled) return crud\n  return apiNotHandled()\n}\n```\n\n### Vue\n\n```vue\n<script setup lang=\"ts\">\n// ✅ Good - Composition API with TypeScript\ninterface Props {\n  label: string\n  disabled?: boolean\n}\n\nconst props = defineProps<Props>()\nconst emit = defineEmits<{\n  click: []\n}>()\n</script>\n```\n\n---\n\n## Module Guidelines\n\n- Each module should be **self-contained**\n- Backend logic in `modules/<module>/supabase/`\n- Frontend in `modules/<module>/ (constants, types, utils, components)`\n- Global components in `nuxt/atomic/`\n- Use `config.json` for metadata\n- Document in `README.md`\n\n---\n\n## Why These Standards\n\n- Aligns with Nuxt, Next, and Supabase patterns\n- Enables horizontal scaling with modules\n- Clear separation backend/frontend\n- Consistent UI with Atomic Design\n- Easy onboarding for contributors\n\n\n",
  "en/about/people-and-credits": "# People & Credits\n\nThe people and projects that make Nucleify possible.\n\n---\n\n## Core Team\n\n### Maintainers\n\nThe people responsible for Nucleify's development and direction.\n\n| Name | Role | GitHub |\n|------|------|--------|\n| Szymon Radomski | Creator & Lead | [@szymcode](https://github.com/szymcode) |\n\n---\n\n## Contributors\n\nThank you to everyone who has contributed to Nucleify!\n\n| Name | GitHub |\n|------|--------|\n| Mścibor Srebrny | [@Mmesek](https://github.com/Mmesek) |\n| Katarzyna Śmierzchalska | [@KatarzynaS97](https://github.com/KatarzynaS97) |\n| Damian Kamyszek | [@K4mD4m](https://github.com/K4mD4m) |\n| Marcin Fuks | [@J0jeQ](https://github.com/J0jeQ) |\n| Jakub Malik | [@JakubMalik](https://github.com/JakubMalik) |\n| Kacper Bujak | [@kbujak09](https://github.com/kbujak09) |\n| – | [@karol199393](https://github.com/karol199393) |\n| Dominika Zalewska | [@domizalewska](https://github.com/domizalewska) |\n| Kamil Błoński | [@kbloski](https://github.com/kbloski) |\n| – | [@Kacper658](https://github.com/Kacper658) |\n| – | [@pysifu](https://github.com/pysifu) |\n\nAll contributors are listed on our [GitHub Contributors](https://github.com/nucleify/nucleify/graphs/contributors) page.\n\n---\n\n## Built With\n\nNucleify is built on top of amazing open source projects:\n\n### Backend & data\n\n| Project | Description |\n|---------|-------------|\n| [Supabase](https://supabase.com) | PostgreSQL, Auth, Storage, Edge Functions |\n| [@supabase/supabase-js](https://github.com/supabase/supabase-js) | JavaScript client |\n\n### Frontend\n\n| Project | Description |\n|---------|-------------|\n| [Nuxt](https://nuxt.com) | Vue.js framework |\n| [Vue.js](https://vuejs.org) | JavaScript framework |\n| [nucleify-ui](https://www.npmjs.com/package/nucleify-ui) | Lit web component library (`nui-*`) |\n| [Vitest](https://vitest.dev) | Testing framework |\n\n### Tooling\n\n| Project | Description |\n|---------|-------------|\n| [Vite](https://vitejs.dev) | Build tool |\n| [TypeScript](https://www.typescriptlang.org) | Type safety |\n| [SCSS](https://sass-lang.com) | CSS preprocessor |\n| [ESLint](https://eslint.org) | JavaScript linting |\n| [Biome](https://biomejs.dev) | Formatting & linting |\n\n---\n\n## Inspiration\n\nProjects and resources that inspired Nucleify:\n\n- [Nucleify modules](/en/docs/core-concepts/modules) – Modular architecture\n- [Feature-Sliced Design](https://feature-sliced.design) – Frontend architecture\n- [Atomic Design](https://atomicdesign.bradfrost.com) – Component hierarchy\n\n---\n\n## Special Thanks\n\n- The Supabase, Vue.js, and React communities\n- Everyone who has reported bugs or suggested features\n- Open source maintainers everywhere\n\n---\n\n## Want to Contribute?\n\nWe welcome contributions of all kinds:\n\n- 🐛 Bug reports\n- 💡 Feature suggestions\n- 📝 Documentation improvements\n- 🔧 Code contributions\n\nSee our [Coding Standards](/en/docs/about/coding-standards) to get started.\n\n---\n\n## License\n\nNucleify is open source software licensed under the [MIT License](https://opensource.org/licenses/MIT).\n\n\n",
  "en/about/philosophy": "# Philosophy\n\n> *\"Stop reinventing the wheel. Start building your product. Now!\"*\n\nThe core principles, values, and vision behind Nucleify.\n\n---\n\n## The Vision\n\nNucleify exists because **modern web development is unnecessarily complex**. Developers spend weeks configuring tools, months rebuilding the same features, and years untangling monolithic codebases. We believe there's a better way.\n\nNucleify is designed to be the **foundation you wish you had** – modular, scalable, performant, and beautiful. A framework that lets you focus on what matters: **building your product**.\n\n---\n\n## The Nucleus Metaphor\n\nLike the nucleus of a cell, Nucleify serves as the **core command center** of your application. Each module is a self-contained unit with its own DNA – complete, functional, and able to exist independently while contributing to the greater organism.\n\nThis isn't just branding. It's architecture:\n\n- **Self-contained modules** – Each feature is complete on its own\n- **Clear boundaries** – Modules communicate through defined interfaces\n- **Organic growth** – Add or remove modules without breaking the system\n- **Collective strength** – Together, modules form something greater\n\n---\n\n## Core Principles\n\n### 1. Modularity is Non-Negotiable\n\n> *\"The secret to building large apps is never build large apps.\"* – Justin Meyer\n\nEverything in Nucleify is a module. Not because it's trendy, but because it works:\n\n| Benefit | Why It Matters |\n|---------|----------------|\n| **Isolation** | Change one module without fear of breaking others |\n| **Reusability** | Use the same module across multiple projects |\n| **Scalability** | Add features without exponential complexity |\n| **Testability** | Test modules independently with confidence |\n| **Team Velocity** | Teams own modules, not files scattered everywhere |\n\n### 2. Full-Stack Unity\n\nBackend and frontend belong together. In Nucleify, every module contains both:\n\n```txt\nmodules/nuc_users/\n├── supabase/           # Migrations, seeders, API handlers\n├── atomic/             # Nuxt / Next UI\n└── vitests/            # Vitest tests\n```\n\nNo more context-switching between repositories. No more API contract confusion. **One module, one feature, one truth.**\n\n### 3. Convention Over Configuration\n\nWe follow Nuxt, Next, and Supabase conventions. Why?\n\n- **Zero decision fatigue** – Focus on building, not configuring\n- **Instant familiarity** – Modern full-stack developers feel at home\n- **Community wisdom** – Battle-tested patterns over reinvention\n- **Predictable structure** – Find any file in seconds\n\n### 4. Performance by Default\n\nNucleify ships with **94+ PageSpeed scores** out of the box:\n\n- SSR & Prerendering with intelligent hydration\n- Atomic Design enables surgical code-splitting\n- Font optimization via `@nuxtjs/google-fonts`\n- Image lazy-loading and format optimization\n- Deferred content loading with `nui-deferred-content`\n- Vite-powered builds with optimal chunking\n\n**Performance isn't an afterthought. It's baked in.**\n\n### 5. Developer Experience First\n\nGreat DX isn't a luxury – it's a multiplier:\n\n- `make` – One command to start everything\n- Clear error messages that point to solutions\n- Hot reload that actually works\n- Type safety across the full stack\n- Documentation that respects your time\n\n---\n\n## Quality Philosophy\n\n### Code Quality\n\n> *\"Always code as if the person who ends up maintaining your code is a violent psychopath who knows where you live.\"* – John Woods\n\n- **Readable over clever** – Code is read 10x more than written\n- **Explicit over implicit** – No magic, no surprises\n- **Small, focused functions** – One function, one job\n- **Meaningful names** – `getUserById()` not `get()`\n- **Type everything** – TypeScript w całym stacku\n\n### Testing Philosophy\n\n- **Test behavior, not implementation** – What it does, not how\n- **High coverage for critical paths** – Auth, payments, data integrity\n- **Fast, reliable tests** – Slow tests don't get run\n- **Vitest** – Frontend and composable tests\n\n### Documentation Philosophy\n\n- **Document the \"why\"** – Code shows \"what\", docs explain \"why\"\n- **Keep docs close to code** – README.md in every module\n- **Update with changes** – Stale docs are worse than no docs\n- **Respect developer time** – Concise, scannable, actionable\n\n---\n\n## Open Source Values\n\n### Transparency\n\nDevelopment happens in the open. Decisions are documented. Roadmaps are public. No black boxes.\n\n### Inclusivity\n\nEvery contribution matters:\n- 🐛 Bug reports improve quality\n- 💡 Feature suggestions shape direction\n- 📝 Documentation helps everyone\n- 🔧 Code contributions build features\n\n### Collaboration\n\nWe build together. Code reviews are learning opportunities. Discussions are respectful. Everyone has a voice.\n\n### Respect\n\nTime is precious. We don't waste yours with:\n- Unnecessary complexity\n- Poor documentation\n- Breaking changes without migration paths\n- Gatekeeping contributions\n\n---\n\n## The Future\n\nNucleify evolves through:\n\n- **Community feedback** – You shape the roadmap\n- **Continuous refinement** – Regular refactoring, never stagnation\n- **Adopting best practices** – Learning from the ecosystem\n- **Maintaining compatibility** – Upgrades shouldn't break your app\n\n> *\"The only constant is change.\"* – Heraclitus\n\nBut some things never change: **modularity, performance, developer experience, and respect for your time.**\n\n---\n\n## Mindset\n\nThe approach that drives every line of code in Nucleify:\n\n---\n\n> *\"This man of little learning grows old like an ox; only his flesh grows but not his wisdom.\"* \\\n> ~ Siddhartha Gautama\n\nNever stop learning. Technology evolves – so must we.\n\n---\n\n> *\"He who has a why to live can bear almost any how.\"* \\\n> ~ Friedrich Nietzsche\n\nPurpose drives persistence. Know why you're building, and obstacles become solvable.\n\n---\n\n> *\"Don't wish it was easier. Wish you were better.\"* \\\n> ~ Jim Rohn\n\nComplexity is inevitable. Grow your skills instead of avoiding challenges.\n\n---\n\n> *\"Fear has never reached the highest goal.\"* \\\n> ~ Bô Yin Râ\n\nDon't fear refactoring, new technologies, or ambitious changes. Courage in code leads to breakthroughs.\n\n---\n\n> *\"Even the idea of resting aggravates my mind.\"* \n\nPassion fuels excellence. Build because you can't not build.\n\n---\n\nBuild with purpose. Ship with confidence.\n\n---\n\n## Join Us\n\n**Build modern. Scale effortlessly. Ship with confidence.**\n\nWe're building something incredible. [Join us.](https://github.com/nucleify/nucleify)\n\n",
  "en/configuration/environment": "# Environment Variables\n\nNucleify reads configuration from `.env` at the repo root. Use `.config/.env.nuxt.example` or `.config/.env.next.example` as a template (`make nuxt` / `make next` copies it automatically).\n\nConfig for Nuxt lives in `.config/nuxt/` and is merged in `.config/nuxt.config.ts`.\n\n## Required (Supabase)\n\n| Variable | Description | Example |\n|----------|-------------|---------|\n| `SUPABASE_URL` | Supabase project URL | `https://xxx.supabase.co` |\n| `SUPABASE_KEY` | Anon/public key (browser-safe) | `eyJhbG…` |\n| `SUPABASE_SERVICE_ROLE_KEY` | Service role (server only) | `eyJhbG…` |\n\nNever expose `SUPABASE_SERVICE_ROLE_KEY` in client bundles or public repos.\n\n## Application\n\n| Variable | Description | Default |\n|----------|-------------|---------|\n| `APP_NAME` | App name | `Nucleify` |\n| `APP_ENV` | Environment | `local` |\n| `APP_DEBUG` | Verbose errors | `true` |\n| `APP_FRONTEND` | Active stack | `nuxt` or `next` |\n| `NUXT_PUBLIC_APP_URL` | Public URL (Nuxt) | `http://localhost:3000` |\n\n## SSR & Prerendering (Nuxt)\n\n```env\nSSR=true\nPRERENDER_ROUTES=/home,/dev,/login,/docs\nPRERENDER_CRAWL_LINKS=true\nPRERENDER_IGNORE=/settings\nPRERENDER_LOCALES=en,pl,vn\nNITRO_PRESET=cloudflare\n```\n\n| Variable | Description |\n|----------|-------------|\n| `SSR` | Enable server-side rendering |\n| `PRERENDER_ROUTES` | Comma-separated routes to prerender |\n| `PRERENDER_CRAWL_LINKS` | Discover links during prerender |\n| `PRERENDER_IGNORE` | Routes to skip |\n| `NITRO_PRESET` | Nitro deploy target |\n\n## Optional\n\n| Variable | Description |\n|----------|-------------|\n| `SUPABASE_EDGE_BASE` | Edge Functions base URL |\n| `NUC_CONVERT_DOCUMENTS_URL` | External document conversion service |\n| `DEV_TOOLS` | Enable Nuxt devtools |\n\n## Example `.env` (Nuxt)\n\n```env\nAPP_NAME=Nucleify\nAPP_ENV=local\nAPP_DEBUG=true\nNUXT_PUBLIC_APP_URL=http://localhost:3000\n\nSUPABASE_URL=https://your-project.supabase.co\nSUPABASE_KEY=your-anon-key\nSUPABASE_SERVICE_ROLE_KEY=your-service-role-key\n\nAPP_FRONTEND=nuxt\nSSR=true\nNITRO_PRESET=cloudflare\n```\n\nSee [Supabase configuration](/en/docs/configuration/supabase) for how these keys are used in the API gateway and client.\n",
  "en/configuration/nuxt": "# Nuxt Configuration\n\nFrontend configuration in `.config/nuxt.config.ts`, re-exported from root `nuxt.config.ts`.\n\n## SSR & Prerendering\n\n```typescript\nssr: process.env.SSR === 'true',\nnitro: {\n  prerender: {\n    routes: process.env.PRERENDER_ROUTES?.split(',') || [],\n    crawlLinks: process.env.PRERENDER_CRAWL_LINKS === 'true',\n    ignore: process.env.PRERENDER_IGNORE?.split(',') || [],\n  },\n  output: { publicDir: './public/build' },\n  minify: true,\n  compressPublicAssets: true,\n},\n```\n\n| Option | Description |\n|--------|-------------|\n| `ssr` | Enable server-side rendering |\n| `prerender.routes` | Routes to prerender at build |\n| `prerender.crawlLinks` | Auto-discover links |\n| `prerender.ignore` | Routes to skip |\n| `minify` | Minify output |\n| `compressPublicAssets` | Gzip/Brotli compression |\n\n## Directory Structure\n\n```typescript\nsrcDir: 'nuxt',\npublicDir: './public',\n```\n\n| Option | Path | Description |\n|--------|------|-------------|\n| `srcDir` | `nuxt/` | Nuxt source files |\n| `publicDir` | `public/` | Static assets |\n\n## Components\n\n```typescript\ncomponents: [\n  { path: '~/atomic/atom', prefix: 'ad', extensions: ['vue'] },\n  { path: '~/atomic/molecule', prefix: 'ad', extensions: ['vue'] },\n  { path: '~/atomic/organism', prefix: 'ad', extensions: ['vue'] },\n]\n```\n\nComponents auto-registered with `ad-` prefix:\n- `<ad-button>`, `<ad-input-text>`, `<ad-card>`, `<ad-dialog>`\n\n## Auto-imports\n\n```typescript\nimports: {\n  dirs: ['~/composables/**', '~/atomic/**', 'modules/**'],\n},\nalias: {\n  nucleify: '~/atomic',\n},\n```\n\nAll exports from these directories are auto-imported. Use `nucleify` alias:\n\n```typescript\nimport { useAuth, type UserInterface } from 'nucleify'\n```\n\n## Runtime Config\n\n```typescript\nruntimeConfig: {\n  public: {\n    appUrl: process.env.APP_URL,\n    apiUrl: process.env.API_URL,\n    appEnv: process.env.APP_ENV,\n  },\n},\n```\n\nAccess in components:\n\n```typescript\nconst config = useRuntimeConfig()\nconst apiUrl = config.public.apiUrl\n```\n\n## App Head\n\n```typescript\napp: {\n  head: {\n    htmlAttrs: { lang: 'en' },\n    title: 'Nucleify - Modular Web Framework',\n    meta: [\n      { charset: 'utf-8' },\n      { name: 'viewport', content: 'width=device-width, initial-scale=1' },\n      { name: 'description', content: '...' },\n    ],\n    link: [\n      { rel: 'icon', type: 'image/x-icon', href: '/favicon.ico' },\n    ],\n  },\n},\n```\n\n## UI (`nucleify-ui`)\n\nLit web components (`nui-*`) are registered by `nuxt/plugins/nucleify-ui.client.ts` (`applyTheme`, global styles). Custom elements matching `nui-` are configured in Vite (`isCustomElement`).\n\n## Vite Build\n\n```typescript\nvite: {\n  build: {\n    chunkSizeWarningLimit: 1600,\n    minify: 'terser',\n    cssCodeSplit: true,\n    rollupOptions: {\n      maxParallelFileOps: 2,\n      output: {\n        manualChunks: {\n          vue: ['vue', 'vue-router', '@unhead/vue'],\n          pinia: ['pinia', 'pinia-plugin-persistedstate'],\n          chartjs: ['chart.js'],\n          gsap: ['gsap'],\n          marked: ['marked'],\n        },\n      },\n    },\n  },\n  optimizeDeps: {\n    include: ['vue', 'vue-router'],\n  },\n},\n```\n\nManual chunks for optimal code splitting and caching. State management: **Pinia** (Nuxt) with `pinia-plugin-persistedstate`; **Zustand** (Next.js) via `nuc_stores`.\n\n## SCSS\n\n```typescript\nvite: {\n  css: {\n    preprocessorOptions: {\n      scss: {\n        additionalData: `@import \"~/assets/index\";`,\n        silenceDeprecations: ['mixed-decls', 'import', 'color-functions', 'global-builtin'],\n      },\n    },\n  },\n},\n```\n\nGlobal SCSS imports available in all components.\n\n## Google Fonts\n\n```typescript\ngoogleFonts: {\n  families: {\n    Inter: '300..700',\n    Nunito: '300..700',\n  },\n  display: 'swap',\n  subsets: ['latin'],\n},\n```\n\n## Icons\n\n```typescript\nicon: {\n  prefix: 'i-prime',\n  mode: 'css',\n},\n```\n\nUse icons with `i-prime` prefix:\n\n```html\n<Icon name=\"i-prime:check\" />\n```\n\n## Supabase Auth\n\nAuthentication uses **Supabase Auth** (JWT sessions). The client is configured via `nuc_client` / `getSupabaseClient()` using `runtimeConfig.public.supabaseUrl` and `supabaseKey`.\n\nLogin and registration flows live in `nuc_users` (`auth/`); the server API gateway uses `SUPABASE_SERVICE_ROLE_KEY` from private runtime config.\n\nSee [Supabase](/en/docs/configuration/supabase) for the full auth and API flow.\n\n## Experimental\n\n```typescript\nexperimental: {\n  payloadExtraction: true,\n  renderJsonPayloads: true,\n},\n```\n\nPerformance optimizations for payload handling.\n\n## Vitalizer\n\n```typescript\nvitalizer: {\n  disableStylesheets: 'entry',\n},\n```\n\nDefers non-critical CSS loading for better Core Web Vitals.\n",
  "en/configuration/supabase": "# Supabase Configuration\n\nNucleify uses **Supabase** as the backend: **PostgreSQL** for data, **Auth** for users, **Storage** for files, and optional **Edge Functions**. The frontend talks to a **module API gateway** on Nuxt/Next server routes that uses the Supabase **service role** client.\n\n---\n\n## How It Works\n\n```txt\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                        NUXT 3 / NEXT (frontend + server routes)                        │\n│                                                                                        │\n│ ┌────────────────────────┐    ┌────────────────────────┐    ┌────────────────────────┐ │\n│ │     Vue / React UI     │───►│    nuc_api (client)    │───►│     /api/* gateway     │ │\n│ │     Pinia / Zustand    │───►│    apiRequest, auth    │───►│    (Nitro / Route)     │ │\n│ └────────────────────────┘    └────────────────────────┘    └────────────────────────┘ │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                            │\n                            modules/*/supabase/api/handle.ts\n                              (per-module route handlers)\n                                            ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                        SUPABASE                                        │\n│                                                                                        │\n│     ┌────────────────┐  ┌────────────────┐  ┌────────────────┐  ┌────────────────┐     │\n│     │   PostgreSQL   │  │      Auth      │  │    Storage     │  │ Edge Functions │     │\n│     │     + RLS      │  │  (JWT users)   │  │   (buckets)    │  │   (optional)   │     │\n│     └────────────────┘  └────────────────┘  └────────────────┘  └────────────────┘     │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n```\n\n### Request flow\n\n1. **Browser** calls `apiRequest('/api/contacts', …)` from `nuc_api` (or module composables built on it).\n2. **Server route** `nuxt/server/api/[...slug].ts` (or Next equivalent) receives the request.\n3. A **Supabase client** is created with `SUPABASE_SERVICE_ROLE_KEY` (server only).\n4. The gateway loops **module handlers** (`handleEntitiesApi`, `handleUsersApi`, …). The first handler that recognizes the path returns JSON.\n5. Handlers use helpers from `nuc_api` (`tryScopedCrud`, `trySimpleCrud`, custom routes) to run **SQL via Supabase JS client** (`supabase.from('table').select()` etc.).\n6. For **auth**, the browser uses the **anon key** (`SUPABASE_KEY`) via `getSupabaseClient()` / `nuc_client` — e.g. `supabase.auth.signInWithPassword`, then profile rows in `user_profiles`.\n\n### Why a gateway instead of only RLS from the browser?\n\n- One **consistent REST shape** for all modules (`/api/{resource}`, `/api/{resource}/{id}`).\n- **Service role** on the server can perform admin operations safely (never expose service role to the client).\n- Module handlers can add **validation, scoping** (`user_id`), and **response formatting** before data hits the UI.\n- Same handlers work on **Nuxt (Nitro)** and **Next (App Router)**.\n\n---\n\n## Environment Variables\n\nCopy `.config/.env.nuxt.example` or `.config/.env.next.example` to `.env` at the repo root.\n\n| Variable | Required | Description |\n|----------|----------|-------------|\n| `SUPABASE_URL` | Yes | Project URL (`https://<ref>.supabase.co`) |\n| `SUPABASE_KEY` | Yes | Anon/public key — safe in browser |\n| `SUPABASE_SERVICE_ROLE_KEY` | Yes (server) | Service role — **server only**, used by `/api/*` gateway |\n| `SUPABASE_EDGE_BASE` | Optional | Base URL for Edge Functions |\n| `NUXT_PUBLIC_APP_URL` | Nuxt | Public app URL (e.g. `http://localhost:3000`) |\n\nNuxt exposes public values via `runtimeConfig.public` in `.config/nuxt/runtime.ts`:\n\n```typescript\npublic: {\n  supabaseUrl: process.env.SUPABASE_URL || '',\n  supabaseKey: process.env.SUPABASE_KEY || '',\n}\n```\n\nPrivate server config:\n\n```typescript\nsupabaseServiceRoleKey: process.env.SUPABASE_SERVICE_ROLE_KEY || '',\n```\n\nNext reads `NEXT_PUBLIC_SUPABASE_URL` / `NEXT_PUBLIC_SUPABASE_KEY` with fallback to `SUPABASE_*` in `next.config.ts`.\n\n---\n\n## Module layout (`supabase/`)\n\nEach module that needs backend logic keeps SQL and handlers next to frontend code:\n\n```txt\nmodules/nuc_example/\n├── config.json\n├── nuc_example.ts              # registerNucExample (Vue)\n├── index.ts                    # barrel\n├── atomic/                     # UI + api composables\n└── supabase/\n    ├── migrations/             # PostgreSQL DDL (*.sql)\n    ├── seeders/                # Seed data (*.sql)\n    ├── factories/              # Test/demo data (*.sql)\n    ├── api/\n    │   ├── handle.ts           # export handleExampleApi(ctx)\n    │   └── *_helpers.ts        # table names, row mapping\n    └── functions/              # Optional Deno Edge Functions\n```\n\n### Registering API handlers\n\n**Nuxt** — add handler to `nuxt/server/api/[...slug].ts`:\n\n```typescript\nimport { handleExampleApi } from '../../../modules/nuc_example/supabase/api/handle'\n\nconst handlers = [\n  // …existing handlers\n  handleExampleApi,\n]\n```\n\n**Next** — register in `modules/nuc_api/supabase/api/gateway_dispatch.ts` (`supabaseApiGatewayHandlers`).\n\nEach handler receives `ApiContext`:\n\n```typescript\ntype ApiContext = {\n  event: H3Event          // or Next request wrapper\n  method: string          // GET, POST, PUT, DELETE\n  segments: string[]      // path after /api/\n  supabase: SupabaseClient\n  ok: (data, extra?) => object\n}\n```\n\nReturn `apiNotHandled()` if the path is not yours; return `apiOk(ctx, data)` or `apiError(status, message)` when handled.\n\n### CRUD helpers (`nuc_api`)\n\n| Helper | Use case |\n|--------|----------|\n| `trySimpleCrud` | Public tables, nested paths like `/api/modules` |\n| `tryScopedCrud` | Rows scoped by `user_id` (contacts, files, …) |\n| Custom routes | `dispatchRoutes` / module-specific handlers (auth, uploads) |\n\n---\n\n## Database: migrations & seeders\n\nSQL files live per module under `supabase/migrations/` and `supabase/seeders/`. The repo merges them into a single file and applies via Supabase CLI:\n\n```bash\n# Merge all module migrations (sorted by filename)\nbash .config/bash/merge-module-supabase-sql.sh migrations\n\n# Apply to local Supabase (requires supabase CLI + running instance)\nbash .config/bash/apply-module-migrations.sh\n\n# Seeders\nbash .config/bash/merge-module-supabase-sql.sh seeders\nbash .config/bash/apply-module-sql.sh seeders\n```\n\nMerged output: `supabase/.temp/merged_migrations.sql`, `merged_seeders.sql`.\n\n**Naming:** `YYYYMMDDHHMMSS_nuc_modulename_description.sql` — same order across all modules.\n\n**RLS:** Migrations typically `enable row level security` and add policies. The API gateway uses the service role; direct client access still respects policies when using the anon key.\n\n---\n\n## Authentication\n\n- **Sign up / login:** `nuc_users` (`auth/`) uses `getSupabaseClient().auth` (email/password, session JWT).\n- **Profile:** After auth, `user_profiles` row is loaded (`getAndSetUser` in `nuc_users/auth`).\n- **API calls:** `apiRequest` sends cookies/headers as configured; server validates scope via Supabase auth uid in handlers.\n- Sessions are **Supabase Auth JWTs**.\n\n---\n\n## Client (`nuc_client`)\n\n```typescript\nimport { getSupabaseClient } from 'nuc_client'\n\nconst supabase = getSupabaseClient()\nconst { data } = await supabase.from('contacts').select('*')\n```\n\n`modules/nuc_api/supabase/client.ts` resolves URL/key from Nuxt `runtimeConfig` or Next `process.env`.\n\n---\n\n## Local development checklist\n\n1. Create a project at [supabase.com](https://supabase.com) (or run `supabase start` locally).\n2. Set `SUPABASE_URL`, `SUPABASE_KEY`, `SUPABASE_SERVICE_ROLE_KEY` in `.env`.\n3. Run migrations: `bash .config/bash/apply-module-migrations.sh`\n4. Run seeders: `bash .config/bash/apply-module-sql.sh seeders`\n5. Start frontend: `make nuxt` or `make next`\n6. Verify gateway: `GET /api/test` → `{ \"message\": \"Hello World\" }`\n\n---\n\n## Production notes\n\n- Never commit **service role** keys; use CI/host secrets.\n- Set `NITRO_PRESET` (e.g. `cloudflare`) for Nuxt deploy; gateway runs as serverless functions.\n- Ensure CORS and `NUXT_PUBLIC_APP_URL` match your deployed domain.\n- Run merged migrations against production DB before deploy.\n",
  "en/core-concepts/atomic-design": "# Atomic Design\n\nNucleify implements Atomic Design methodology to create consistent, scalable, and maintainable UI systems.\n\n## What is Atomic Design?\n\nAtomic Design is a methodology created by Brad Frost that breaks down user interfaces into fundamental building blocks. Inspired by chemistry, it organizes components into a hierarchy from the smallest elements to complete pages.\n\n**Key benefits:**\n- **Consistency** - Reusable components ensure uniform look and feel\n- **Maintainability** - Changes propagate automatically through the system\n- **Scalability** - Easy to extend without breaking existing functionality\n- **Collaboration** - Clear structure improves team communication\n\n---\n\n## Core Principle: No Business Logic\n\n> **Atomic Design components must NOT contain business logic.**\n\nComponents should only include functionality directly related to their UI behavior:\n\n| ✅ Allowed | ❌ Not Allowed |\n|-----------|---------------|\n| Input validation (format, length) | Hardcoded API calls |\n| Animation and transitions | Direct data fetching |\n| Local component state | Store mutations |\n| Event emission | Hardcoded URLs or endpoints |\n| Prop-based rendering | Authentication/authorization checks |\n| Accessibility features | Domain-specific calculations |\n| Configurable callbacks via props | Inflexible business rules |\n| Generic event handlers | Hardcoded configuration |\n\n**Business logic belongs in:**\n- Stores (Pinia / Zustand)\n- Composables\n- Services\n\n### Exceptions\n\nNucleify extends the original Atomic Design with dedicated modules that **are allowed to contain business logic**:\n\n| Module | Purpose |\n|--------|---------|\n| `nuc_templates` | Reusable templates for individual components (cards, forms, modals) |\n| `nuc_templates` | Page sections with layout logic, data handling, section-specific behavior |\n| `nuc_pages` | Full page components with API calls, store access, business rules |\n\nThese modules were intentionally separated from `nuxt/atomic/` because they serve as integration points where UI meets application logic. By isolating business logic here, all other atomic components remain pure, and reusable.\n\n---\n\n## The Hierarchy\n\nNucleify extends the original Atomic Design with an additional layer called **Bosons** for types and utilities.\n\n```txt\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                       Bosons                                           │\n│                      Types, utilities, constants (invisible layer)                     │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                        Atoms                                           │\n│                        Basic UI elements (Button, Input, Icon)                         │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                      Molecules                                         │\n│                    Simple combinations of atoms (FloatLabel, Tile)                     │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                      Organisms                                         │\n│                     Complex UI sections (DataTable, Dialog, Menu)                      │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                              Templates  (nuc_templates)                                │\n│                   Reusable component templates (cards, forms, modals)                  │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                               Sections  (nuc_templates)                                 │\n│                    Page sections with layout and data handling                         │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                 Pages  (nuc_pages)                                     │\n│                  Full pages with API calls, stores, business rules                     │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Bosons - The Invisible Foundation\n\nBosons are the smallest, indivisible pieces of reusable logic. They don't render anything but provide the foundation for all components.\n\n**What belongs in Bosons:**\n- TypeScript interfaces and types\n- Pure utility functions (no side effects)\n- Constants and enums\n- Component-specific helpers\n\n```typescript\n// types/interfaces.ts\nexport interface ButtonInterface {\n  label?: string\n  variant?: 'primary' | 'secondary' | 'danger'\n  disabled?: boolean\n}\n\n// utils/format_date.ts\nexport function formatDate(date: Date): string {\n  return new Intl.DateTimeFormat('en-US').format(date)\n}\n\n// constants/breakpoints.ts\nexport const BREAKPOINTS = {\n  mobile: 768,\n  tablet: 1024,\n  desktop: 1440,\n} as const\n```\n\n---\n\n## Atoms - Basic Building Blocks\n\nAtoms are the smallest visual components. They cannot be broken down further without losing their meaning.\n\n**Examples:** Button, Input, Icon, Label, Badge, Checkbox, Avatar\n\n**What logic is allowed:**\n- Handling click/focus/hover events\n- Managing internal state (e.g., input value)\n- Applying conditional styles based on props\n- Emitting events to parent\n\n```html\n<template>\n  <button\n    :class=\"[\n      $style['ad-button'],\n      variant && $style[variant],\n    ]\"\n    :disabled=\"disabled\"\n    @click=\"$emit('click', $event)\"\n  >\n    <slot />\n  </button>\n</template>\n\n<script setup lang=\"ts\">\nimport type { ButtonInterface } from './types'\n\ndefineProps<ButtonInterface>()\ndefineEmits<{ click: [event: MouseEvent] }>()\n</script>\n\n<style lang=\"scss\" module>\n.ad-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.75rem 1.5rem;\n  border-radius: 0.5rem;\n  font-weight: 500;\n  cursor: pointer;\n  transition: all 0.2s ease;\n\n  &.primary {\n    background: var(--primary-color);\n    color: white;\n  }\n\n  &.secondary {\n    background: transparent;\n    border: 1px solid var(--border-color);\n  }\n}\n</style>\n```\n\n**Folder structure:**\n\n```txt\natomic/atom/button/\n├── index.vue            # Component\n├── index.ts             # Exports\n├── _index.scss          # Styles (optional)\n└── types/\n    ├── index.ts\n    ├── interfaces.ts\n    └── variables.ts     # Type literals\n```\n\n---\n\n## Molecules - Simple Combinations\n\nMolecules combine atoms into functional units. They have a single responsibility and are still relatively simple.\n\n**Examples:** FloatLabel, Anchor, Tile\n\n**What logic is allowed:**\n- Coordinating child atom states\n- Simple computed values\n- Local validation (format only, not business rules)\n\n```html\n<template>\n  <div :class=\"$style['float-label']\">\n    <ad-input\n      :id=\"inputId\"\n      v-model=\"model\"\n      :placeholder=\"placeholder\"\n    />\n    <ad-label :for=\"inputId\">\n      {{ label }}\n    </ad-label>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { FloatLabelInterface } from './types'\n\nconst props = defineProps<FloatLabelInterface>()\nconst model = defineModel<string>()\nconst inputId = computed(() => props.id || `input-${Math.random()}`)\n</script>\n```\n\n**When to create a molecule:**\n- Two or more atoms always appear together\n- The combination has specific interaction logic\n- It represents a single, cohesive UI function\n\n**Folder structure:**\n\n```txt\nnuxt/atomic/molecule/\n├── float-label/\n│   ├── index.vue\n│   ├── index.ts\n│   └── types/\n├── anchor/\n├── tile/\n└── index.ts\n```\n\n---\n\n## Organisms - Complex Structures\n\nOrganisms are complex UI sections composed of molecules, atoms, or other organisms. They are still **presentation-only** components.\n\n**Examples:** DataTable, Dialog, Menu, Card, Accordion, Navbar\n\n**What logic is allowed:**\n- Rendering data passed via props\n- Local filtering/sorting of provided data\n- Managing open/closed states\n- Emitting events for user actions\n\n**What is NOT allowed:**\n- Fetching data from APIs\n- Direct store access\n- Business rule validation\n\n```html\n<template>\n  <div :class=\"$style['data-table']\">\n    <div :class=\"$style.header\">\n      <ad-input\n        v-model=\"searchQuery\"\n        placeholder=\"Search...\"\n      />\n    </div>\n\n    <table>\n      <thead>\n        <tr>\n          <th v-for=\"col in columns\" :key=\"col.field\">\n            {{ col.header }}\n          </th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr v-for=\"row in filteredData\" :key=\"row.id\">\n          <td v-for=\"col in columns\" :key=\"col.field\">\n            {{ row[col.field] }}\n          </td>\n        </tr>\n      </tbody>\n    </table>\n\n    <ad-pagination\n      v-model=\"currentPage\"\n      :total=\"totalPages\"\n      @change=\"$emit('page-change', $event)\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { DataTableInterface } from './types'\n\n// ✓ Props for data - component doesn't fetch anything\nconst props = defineProps<DataTableInterface>()\n\n// ✓ Local UI state only\nconst searchQuery = ref('')\nconst currentPage = ref(1)\n\n// ✓ Local filtering - no business logic\nconst filteredData = computed(() =>\n  props.data.filter(row =>\n    Object.values(row).some(v =>\n      String(v).toLowerCase().includes(searchQuery.value.toLowerCase())\n    )\n  )\n)\n\n// ✓ Emit events - let parent handle business logic\ndefineEmits<{ 'page-change': [page: number] }>()\n</script>\n```\n\n**Folder structure:**\n\n```txt\nnuxt/atomic/organism/\n├── data-table/\n│   ├── index.vue\n│   ├── index.ts\n│   ├── _index.scss\n│   └── types/\n├── dialog/\n├── menu/\n├── card/\n└── index.ts\n```\n\n---\n\n## Templates\n\nTemplates are reusable component wrappers for cards, forms, modals, and other structured layouts. Business logic is allowed here.\n\n**Location:** `modules/nuc_templates/`\n\n```html\n<template>\n  <div :class=\"$style['dashboard-template']\">\n    <aside :class=\"$style.sidebar\">\n      <slot name=\"sidebar\" />\n    </aside>\n    <main :class=\"$style.content\">\n      <header>\n        <slot name=\"header\" />\n      </header>\n      <slot />\n    </main>\n  </div>\n</template>\n```\n\n**Folder structure:**\n\n```txt\nmodules/nuc_templates/\n├── atomic/\n│   └── templates/\n│       ├── dashboard/\n│       │   ├── index.vue\n│       │   ├── index.ts\n│       │   └── types/\n│       ├── auth/\n│       ├── card/\n│       └── index.ts\n├── config.json\n└── index.ts\n```\n\n---\n\n## Sections\n\nSections are page-level building blocks with layout logic and data handling. They compose templates and organisms into meaningful page areas.\n\n**Location:** `modules/nuc_templates/`\n\n```html\n<template>\n  <section :class=\"$style['hero-section']\">\n    <div :class=\"$style.content\">\n      <ad-heading>{{ title }}</ad-heading>\n      <ad-paragraph>{{ description }}</ad-paragraph>\n      <ad-button @click=\"handleAction\">{{ actionLabel }}</ad-button>\n    </div>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport type { HeroSectionInterface } from './types'\n\n// ✓ Business logic allowed in sections\nconst props = defineProps<HeroSectionInterface>()\n\nconst emit = defineEmits<{ action: [] }>()\n\nfunction handleAction() {\n  // Can contain business logic\n  emit('action')\n}\n</script>\n```\n\n**Folder structure:**\n\n```txt\nmodules/nuc_templates/\n├── atomic/\n│   └── sections/\n│       ├── hero/\n│       │   ├── index.vue\n│       │   ├── index.ts\n│       │   └── types/\n│       ├── features/\n│       ├── pricing/\n│       └── index.ts\n├── config.json\n└── index.ts\n```\n\n---\n\n## Pages\n\nPages are where **business logic lives**. They connect UI components with stores, APIs, and application state.\n\n| Part | Location | Purpose |\n|------|----------|---------|\n| Route definition | `nuxt/pages/` | Nuxt routing (minimal wrapper) |\n| Page content | `modules/nuc_pages/pages/` | Business logic + component composition |\n\n**Route file** (`nuxt/pages/dashboard.vue`):\n\n```html\n<template>\n  <nuc-dashboard-page />\n</template>\n```\n\n**Page component** (`modules/nuc_pages/pages/Dashboard/index.vue`):\n\n```html\n<template>\n  <dashboard-template>\n    <template #sidebar>\n      <navigation-menu :items=\"menuItems\" />\n    </template>\n\n    <!-- ✓ Data passed to presentation component -->\n    <ad-data-table\n      :data=\"users\"\n      :columns=\"columns\"\n      @page-change=\"handlePageChange\"\n    />\n  </dashboard-template>\n</template>\n\n<script setup lang=\"ts\">\n// ✓ Business logic lives here\nconst userStore = useUserStore()\nconst { users, fetchUsers } = userStore\n\n// ✓ API calls in pages\nonMounted(() => fetchUsers())\n\n// ✓ Business logic handlers\nfunction handlePageChange(page: number) {\n  fetchUsers({ page })\n}\n</script>\n```\n\n**Folder structure:**\n\n```txt\nmodules/nuc_pages/\n├── pages/\n│   ├── Dashboard/\n│   │   ├── index.vue\n│   │   ├── index.ts\n│   │   └── types/\n│   ├── Home/\n│   ├── Profile/\n│   └── index.ts\n├── config.json\n└── index.ts\n```\n\n---\n\n## Component Naming Conventions\n\nAll atomic components use the `ad-` prefix (Atomic Design):\n\n| Level | Naming | Example |\n|-------|--------|---------|\n| Atom | `ad-{name}` | `<ad-button>`, `<ad-icon>` |\n| Molecule | `ad-{name}` | `<ad-float-label>`, `<ad-tile>` |\n| Organism | `ad-{name}` | `<ad-data-table>`, `<ad-dialog>` |\n| Template | `nuc-{module}-{name}` | `<nuc-auth-template>` |\n| Page | `nuc-{module}-page` | `<nuc-dashboard-page>` |\n\n---\n\n## Best Practices\n\n### 1. Keep Components Pure\n\nComponents should be predictable - same props always produce same output:\n\n```html\n<!-- ✓ Good: Pure presentation -->\n<ad-user-card :user=\"user\" @follow=\"$emit('follow', user.id)\" />\n\n<!-- ✗ Bad: Side effects inside component -->\n<ad-user-card :userId=\"userId\" />  <!-- fetches user internally -->\n```\n\n### 2. Props Down, Events Up\n\nComponents receive data via props and communicate changes via events:\n\n```html\n<!-- Parent handles business logic -->\n<ad-select\n  v-model=\"selectedOption\"\n  :options=\"options\"\n  @change=\"saveToApi\"\n/>\n```\n\n### 3. Single Responsibility\n\nEach component should do one thing well:\n\n```html\n<!-- ✓ Good: Focused component -->\n<ad-avatar :src=\"user.avatar\" :size=\"'lg'\" />\n\n<!-- ✗ Bad: Too many responsibilities -->\n<user-card-with-avatar-and-actions-and-menu />\n```\n\n### 4. Use TypeScript Interfaces\n\nAlways define prop interfaces for type safety:\n\n```typescript\n// types/interfaces.ts\nexport interface CardInterface {\n  title?: string\n  subtitle?: string\n  variant?: CardVariant\n  clickable?: boolean\n}\n\n// types/variables.ts\nexport type CardVariant = 'default' | 'outlined' | 'elevated'\n```\n\n",
  "en/core-concepts/feature-sliced-design": "# Feature-Sliced Design\n\nFeature-Sliced Design (FSD) organizes code by business domain instead of technical layers. Each module is a self-contained unit with its own frontend, backend, database, and tests.\n\n## Key Rules\n\n- One feature per module\n- Export only what's needed via `index.ts`\n- Keep modules small - split when needed\n- Co-locate tests with code\n\n## Traditional vs Feature-Sliced\n\n```txt\n# ❌ By layer                    # ✅ By domain\nsrc/                             modules/\n├── api/                         ├── nuc_users/\n│   ├── auth-handler.ts          │   ├── supabase/api/handle.ts\n│   └── user-handler.ts          │   ├── supabase/migrations/\n├── db/                          │   ├── pages/\n│   └── users.sql                │   └── vitests/\n└── ui/                          └── nuc_entities/\n    └── auth/                        ├── supabase/api/handle.ts\n                                     └── pages/\n```\n\n## Benefits\n\n| Benefit | Description |\n|---------|-------------|\n| **High cohesion** | All related code in one place |\n| **Low coupling** | Modules are independent, enable/disable via `config.json` |\n| **Clear boundaries** | Explicit API through `index.ts` exports |\n| **Team scalability** | Teams work on separate modules without conflicts |\n| **Easy testing** | Tests co-located with the code they test |\n\n## Layer Dependencies\n\n**Backend (`supabase/`):**\n`api/handle.ts` → helpers → PostgreSQL (migrations, RLS)\n\n**Frontend (`atomic/`):**\npages → templates → bosons (types, utils, constants)\n\n## Cross-Module Imports\n\n```typescript\nimport { userRequests, type UserInterface } from 'modules/nuc_entities'\n```\n\nShared utilities in dedicated modules: `nuc_api`, `nuc_globals`, `nuc_stores`\n\n## Quick Comparison\n\n| Aspect | Layered | Feature-Sliced |\n|--------|---------|----------------|\n| Find code | Multiple folders | One folder |\n| Add feature | Touch many places | Add one folder |\n| Remove feature | Hunt scattered files | Delete one folder |\n",
  "en/core-concepts/modules": "# Modules\n\nModules are the core organizational unit in Nucleify. They encapsulate related functionality into reusable packages that work across **Supabase** (backend SQL + API handlers) and **Vue/Nuxt** or **React/Next** (frontend).\n\n## Naming Convention\n\n| Type | Prefix | Example |\n|------|--------|---------|\n| Core modules | `nuc_` | `nuc_users`, `nuc_entities` |\n| Custom modules | `your_prefix_` | `ex_payments`, `my_blog` |\n\nCore modules (`nuc_*`) are maintained by Nucleify. Custom modules should use a unique prefix to avoid conflicts.\n\n## Module Structure\n\n```txt\nmodules/ex_example/\n├── config.json              # Module metadata (required)\n├── ex_example.ts            # Vue component registration\n├── ex_example.react.ts      # React registration (optional)\n├── index.ts                 # TypeScript barrel export\n├── _index.scss              # SCSS entry point\n├── README.md\n├── atomic/                  # UI components & composables\n├── supabase/                # Backend: SQL + API handlers\n│   ├── migrations/\n│   ├── seeders/\n│   ├── factories/\n│   └── api/handle.ts\n└── vitests/                 # Vitest tests\n```\n\n## Required Files\n\n### `config.json`\n\nModule metadata and state:\n\n```json\n{\n  \"name\": \"ex_example\",\n  \"description\": \"Example module description\",\n  \"version\": \"0.0.1\",\n  \"category\": \"feature\",\n  \"installed\": true,\n  \"enabled\": true\n}\n```\n\n| Field | Description |\n|-------|-------------|\n| `name` | Unique identifier, must match folder name |\n| `description` | Brief module purpose |\n| `version` | Semantic version |\n| `category` | `core`, `feature`, or `utility` |\n| `installed` | Whether module is installed |\n| `enabled` | Whether module is active |\n\n### `ex_example.ts`\n\nVue global component registration:\n\n```typescript\nimport type { App } from 'vue'\nimport { ExExamplePage } from './atomic'\n\nexport function registerExExample(app: App<Element>): void {\n  app.component('ex-example-page', ExExamplePage)\n}\n```\n\nRegister in `nuxt/plugins/modules.ts` via `registerExExample`.\n\n### `supabase/api/handle.ts`\n\nAPI handler for the module gateway:\n\n```typescript\nimport { apiNotHandled, trySimpleCrud } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleExampleApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  if (ctx.segments[0] !== 'examples') return apiNotHandled()\n  return (await trySimpleCrud(ctx, { table: 'examples' })) ?? apiNotHandled()\n}\n```\n\nAdd `handleExampleApi` to `nuxt/server/api/[...slug].ts` handlers array.\n\n### `index.ts`\n\nBarrel export for all module exports:\n\n```typescript\nexport * from './ex_example'\nexport * from './atomic'\nexport * from './vitests'\n```\n\nAdd to `modules/index.ts`:\n\n```typescript\nexport * from './ex_example'\n```\n\n## Backend Structure (`supabase/`)\n\n```txt\nsupabase/\n├── migrations/                     # PostgreSQL schema (*.sql)\n├── seeders/                        # Seed data\n├── factories/                      # Demo/test data\n├── api/\n│   ├── handle.ts                   # Gateway entry: handleExampleApi\n│   └── *_helpers.ts                # Table names, row mapping\n└── functions/                      # Optional Edge Functions\n```\n\nHandlers use `nuc_api` helpers (`trySimpleCrud`, `tryScopedCrud`) and the Supabase JS client passed in `ApiContext`.\n\n## Frontend Structure (`atomic/`)\n\nUses Atomic Design methodology:\n\n```txt\natomic/\n├── index.ts                        # Barrel export\n├── _index.scss                     # SCSS imports\n├── bosons/                         # Utilities & types (smallest units)\n│   ├── constants/                  # Static values\n│   │   └── fields/                 # Form field definitions\n│   ├── types/                      # TypeScript interfaces\n│   │   ├── api/                    # API response types\n│   │   └── object/                 # Domain object types\n│   └── utils/                      # Helper functions\n│       └── api/                    # API request functions\n├── pages/                          # Full page components\n│   └── General/\n│       ├── index.ts\n│       └── index.vue\n└── templates/                      # Page sections/layouts\n    └── Dashboard/\n        ├── index.ts\n        └── General.vue\n```\n\n### Bosons\n\nSmallest building blocks - types, constants, utilities:\n\n```typescript\n// types/api/interfaces.ts\nexport interface ExampleApiResponse {\n  id: number\n  name: string\n  created_at: string\n}\n\n// utils/api.ts\nexport async function getExamples(): Promise<ExampleApiResponse[]> {\n  return await api.get('/api/examples')\n}\n```\n\n### Pages\n\nFull-page Vue components:\n\n```html\n<!-- pages/General/index.vue -->\n<template>\n  <ExExampleDashboard />\n</template>\n\n<script setup lang=\"ts\">\nimport { ExExampleDashboard } from '../../templates'\n</script>\n```\n\n### Templates\n\nReusable page sections:\n\n```html\n<!-- components/Dashboard/General.vue -->\n<template>\n  <section class=\"ex-example-dashboard\">\n    <slot />\n  </section>\n</template>\n```\n\n## Database (`supabase/migrations/`)\n\n```txt\nsupabase/migrations/\n└── 20260501000000_nuc_example.sql\n```\n\nApply with `bash .config/bash/apply-module-migrations.sh` (merges all module SQL).\n\n## API routes\n\nThe gateway maps `/api/{segments}` to module handlers. Example: `GET /api/examples` → `handleExampleApi` → `supabase.from('examples').select()`.\n\n## Testing\n\n### Vitest (`vitests/`)\n\nFrontend unit tests:\n\n```txt\nvitests/\n├── index.ts                        # Barrel export\n├── api/                            # API request tests\n│   └── Example/\n│       └── 200.test.ts\n└── constants/                      # Test constants\n    └── api/\n        └── example.ts\n```\n\n## Creating a Module\n\n1. **Create folder**: `modules/yourprefix_modulename/`\n\n2. **Add `config.json`** with module metadata\n\n3. **Create entry points**:\n   - `yourprefix_modulename.ts` (Vue) and/or `.react.ts` (React)\n   - `index.ts` (always required)\n   - `supabase/api/handle.ts` (if API needed)\n\n4. **Register module**:\n   - Add handler to `nuxt/server/api/[...slug].ts` (and Next gateway if used)\n   - Add to `modules/index.ts` and `nuxt/plugins/modules.ts`\n\n5. **Add structure** as needed:\n   - `atomic/` for UI\n   - `supabase/migrations`, `seeders` for database\n   - `vitests/` for tests\n\n## Best Practices\n\n- **Naming**: Use unique prefix (`nuc_` is reserved for core modules)\n- **Exports**: Export everything through `index.ts` files\n- **Types**: Define all TypeScript types in `types/`\n- **API**: Keep API logic in `utils/api.ts`\n- **Testing**: Prefer Vitest for UI and API composables\n- **SCSS**: Use `_index.scss` for module-specific styles\n- **Documentation**: Include `README.md` in each module\n",
  "en/core-concepts/overriding": "# Overriding\n\nOverrides allow you to replace original files without modifying source code. This enables custom client implementations without editing core files, while maintaining clean upgrade paths.\n\nSupported overrides:\n- **Frontend** (Vue, TypeScript): `nuxt/`, `modules/*`\n- **Backend** (Supabase SQL, API handlers): `modules/*/supabase/`\n\n## Key Rules\n\n- Override files must have the **exact same path** as originals\n- Override files **completely replace** originals (no merging)\n- Copy the original folder, delete files you don't override, **keep only what you change**\n- Only override what you **need to change**\n- Test thoroughly - overrides may break with updates\n\n## How It Works\n\nPlace files in the `overrides/` directory with the same structure as the original:\n\n```txt\noverrides/\n├── nuxt/                    # Overrides for nuxt/ directory\n│   ├── composables/\n│   ├── pages/\n│   └── ...\n└── modules/                 # Overrides for modules/ directory\n    └── nuc_users/\n        ├── atomic/\n        └── supabase/\n```\n\nThe system automatically:\n- **Frontend**: Redirects imports, excludes originals from build, handles all import types\n- **Backend**: Same mechanism for `supabase/api/*.ts` handlers imported by the API gateway (TypeScript overrides)\n\n## Common Use Cases\n\n### Custom Authentication\n\n```txt\noverrides/\n└── modules/\n    └── nuc_users/\n        ├── atomic/\n        │   └── pages/\n        │       └── Login/\n        │           └── index.vue      # Custom login UI\n        └── supabase/\n            └── api/\n                └── handle.ts              # Custom API logic\n```\n\n### Custom API handler\n\n```txt\noverrides/\n└── modules/\n    └── nuc_entities/\n        └── supabase/\n            └── api/\n                └── handle.ts           # Extra validation or custom queries\n```\n\n### Custom Dashboard\n\n```txt\noverrides/\n└── nuxt/\n    └── pages/\n        └── dashboard.vue              # Custom dashboard layout\n```\n\n## Frontend Overrides\n\n### Vue Components\n\nOriginal: `modules/nuc_users/auth/pages/login.vue`\n\nOverride: `overrides/modules/nuc_users/auth/pages/login.vue`\n\n```html\n<template>\n  <div class=\"custom-login\">\n    <!-- Your custom login UI -->\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n// Your custom logic\n</script>\n```\n\n### TypeScript Files\n\nOriginal: `nuxt/composables/useAuth.ts`\n\nOverride: `overrides/nuxt/composables/useAuth.ts`\n\n```typescript\nexport function useAuth() {\n  // Your custom authentication logic\n}\n```\n\n### Nuxt Pages\n\nOriginal: `nuxt/pages/dashboard.vue`\n\nOverride: `overrides/nuxt/pages/dashboard.vue`\n\n## Backend Overrides\n\n### API handlers\n\nOriginal: `modules/nuc_users/supabase/api/handle.ts`\n\nOverride: `overrides/modules/nuc_users/supabase/api/handle.ts`\n\n```typescript\nimport { apiNotHandled } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleAuthApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  // Your custom handler logic\n  return apiNotHandled()\n}\n```\n\n### SQL migrations\n\nFor schema changes specific to your deployment, prefer new migration files in your own module rather than overriding core SQL. If you must override seed data, mirror the path under `overrides/modules/<module>/supabase/seeders/`.\n\n## Technical Details\n\n### Frontend (Vite Plugin)\n\nThe override system uses a Vite plugin that:\n1. Scans `overrides/nuxt/` and `overrides/modules/` on startup\n2. Creates a mapping of original → override paths\n3. Intercepts file loads and returns override content\n4. Watches for changes and hot-reloads\n\nServer-side API handlers under `modules/*/supabase/api/` use the same resolution when imported through the Nuxt/Next build.\n",
  "en/getting-started/installation": "# Installation\n\n## Ready in Under 5 Minutes\n\nNucleify is a **Nuxt 3** or **Next.js** frontend with a **Supabase** backend. One `make` command copies env config, installs dependencies, and starts the dev server.\n\n---\n\n## Prerequisites\n\n| Requirement | Version | Check Command |\n|-------------|---------|---------------|\n| **Node.js** | 20.x+ | `node --version` |\n| **pnpm** | 9.x+ | `pnpm --version` |\n| **Git** | Latest | `git --version` |\n| **Supabase CLI** | Latest (for DB) | `supabase --version` |\n\nYou also need a Supabase project ([supabase.com](https://supabase.com)) or a local instance (`supabase start`).\n\n---\n\n## One-Command Setup\n\n### 1. Clone the Repository\n\n```bash\ngit clone https://github.com/Nucleify/Nucleify.git\ncd Nucleify\n```\n\n### 2. Choose Frontend & Run\n\n**Nuxt (default):**\n\n```bash\nmake nuxt\n```\n\n**Next.js:**\n\n```bash\nmake next\n```\n\n**Both** (install deps once, then pick manually):\n\n```bash\nmake setup\n```\n\n---\n\n## What `make` Does\n\n```bash\ncp .config/.env.nuxt.example .env   # or .env.next.example\npnpm install\npnpm prepare:husky\npnpm nuxt                            # or pnpm next\n```\n\nConfigure Supabase keys in `.env` before using API features (see [Environment](/en/docs/configuration/environment)).\n\n---\n\n## Database Setup\n\nAfter Supabase is running and `.env` is filled:\n\n```bash\nbash .config/bash/apply-module-migrations.sh\nbash .config/bash/apply-module-sql.sh seeders\n```\n\nThis merges SQL from all enabled modules under `modules/*/supabase/` and applies it to your database.\n\n---\n\n## Access Your Application\n\n| Service | URL |\n|---------|-----|\n| **Nuxt** | `http://localhost:3000` |\n| **Next** | `http://localhost:3001` (if port 3000 is taken) |\n| **API gateway** | `http://localhost:3000/api/test` |\n| **Supabase Studio** | Local: `http://localhost:54323` (with `supabase start`) |\n\n---\n\n## Troubleshooting\n\n### Missing Supabase config\n\nEnsure `SUPABASE_URL`, `SUPABASE_KEY`, and `SUPABASE_SERVICE_ROLE_KEY` are set in `.env`.\n\n### Port conflicts\n\nStop other apps on 3000/3001 or set a custom port for Next/Nuxt.\n\n### Migration errors\n\nRe-run merge and apply:\n\n```bash\nbash .config/bash/merge-module-supabase-sql.sh migrations\nbash .config/bash/apply-module-migrations.sh\n```\n\n---\n\n## Next Steps\n\n1. **[Supabase](/en/docs/configuration/supabase)** — How the backend and API gateway work\n2. **[Quick Start](/en/docs/getting-started/quick-start)** — Create your first component\n3. **[Modules](/en/docs/core-concepts/modules)** — Module structure\n",
  "en/getting-started/introduction": "# Introduction\n\n## Build faster. Scale effortlessly. Ship with confidence.\n\n**Nucleify** is the modular full-stack framework that eliminates the chaos of modern web development. One command to start. 40+ battle-tested modules ready to deploy. Zero configuration overhead.\n\n> *\"Stop reinventing the wheel. Start building your product. Now!\"*\n\nPowered by **Supabase** + **Nuxt 3** / **Next.js** — Nucleify gives you a modular full-stack app with PostgreSQL, Auth, and a unified module API gateway, plus 94+ PageSpeed scores out of the box.\n\n---\n\n## What is Nucleify?\n\nBehind the speed is a **nucleus-inspired modular architecture** - every feature lives as a self-contained, independently testable module. No more tangled dependencies. No more \"it works on my machine\". Just clean, predictable code that scales with your team and your ambitions.\n\n**Supabase** stores data, authenticates users, and serves files. **Nuxt 3** or **Next.js** delivers SSR and a reactive UI. Module handlers in `supabase/api/` connect the two through `/api/*` — one codebase, one workflow.\n\n### The Numbers\n\n| Metric | Value |\n|--------|-------|\n| **Time to MVP** | < 5 minutes setup |\n| **Accessibility** | WCAG 2.1 AA compliant |\n| **PageSpeed Score** | 94/100 |\n| **SEO Score** | 100/100 |\n| **Test Coverage** | 92% |\n| **Production-Ready Modules** | 40+ |\n| **UI Components** | 100+ |\n\n### What You Get\n\n- **40+ Production-Ready Modules** - Auth, files, charts, datatables, animations - all pre-built\n- **Full-Stack Type Safety** - TypeScript end to end, typed API composables\n- **Atomic Design System** - 100+ components following industry best practices\n- **Override System** - Customize any module without forking, preserve upgrade paths\n- **One-Command Setup** - `make` and you're running\n\n---\n\n## Why Choose Nucleify?\n\n| Challenge | ❌ Traditional Approach | ✅ Nucleify Solution |\n|-----------|---------------------|-------------------|\n| **Growing Complexity** | Monolithic codebase becomes unmanageable | Self-contained modules scale independently |\n| **Code Reusability** | Copy-paste across projects | Modules are portable and shareable |\n| **Testing Difficulty** | Tightly coupled code is hard to test | Isolated modules enable focused testing |\n| **Team Collaboration** | Merge conflicts and stepping on toes | Teams own specific modules |\n\n---\n\n## Architecture Overview\n\nNucleify connects the **frontend** to **Supabase** through a module API gateway:\n\n```txt\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                          NUXT 3 / NEXT (frontend + /api routes)                        │\n│                                                                                        │\n│  ┌────────────────────┐  ┌────────────────────┐  ┌──────────────────────────────────┐  │\n│  │       Pages        │  │      Layouts       │  │        Atomic Components         │  │\n│  │      (Router)      │  │  (Default, Admin)  │  │  (Atoms, Molecules, Organisms)   │  │\n│  └────────────────────┘  └────────────────────┘  └──────────────────────────────────┘  │\n│                                           │                                            │\n│  ┌────────────────────────────────────────▼─────────────────────────────────────────┐  │\n│  │                        PINIA / ZUSTAND STATE MANAGEMENT                         │  │\n│  └────────────────────────────────────────┬─────────────────────────────────────────┘  │\n│                                           │                                            │\n│  ┌────────────────────────────────────────▼─────────────────────────────────────────┐  │\n│  │                    nuc_api — apiRequest, Supabase Auth (client)                  │  │\n│  └────────────────────────────────────────┬─────────────────────────────────────────┘  │\n└───────────────────────────────────────────┼────────────────────────────────────────────┘\n                                            │  /api/*\n┌───────────────────────────────────────────▼────────────────────────────────────────────┐\n│                        MODULE HANDLERS (supabase/api/handle.ts)                        │\n│                         nuc_api gateway — service role client                          │\n└───────────────────────────────────────────┬────────────────────────────────────────────┘\n                                            │\n┌───────────────────────────────────────────▼────────────────────────────────────────────┐\n│                                  SUPABASE (PostgreSQL)                                 │\n│                         Auth · Storage · RLS · Edge Functions                          │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Core Design Principles\n\n### Atomic Design\n\nUI components organized into a hierarchical structure for maximum reusability. All components use the `ad-` prefix (Atomic Design):\n\n| Level | Description | Examples |\n|-------|-------------|----------|\n| **Boson** | Utility functions, constants, types | `camelToKebab()`, `API_BASE_URL` |\n| **Atom** | Fundamental UI elements | `<ad-button>`, `<ad-input-text>`, `<ad-avatar>` |\n| **Molecule** | Combinations of atoms | `<ad-float-label>`, `<ad-anchor>`, `<ad-tile>` |\n| **Organism** | Complex component structures | `<ad-data-table>`, `<ad-dialog>`, `<ad-chart>` |\n\n### Modular Architecture\n\nNucleify ships with production-ready modules organized by domain:\n\n| Category | Modules |\n|----------|---------|\n| **Core** | `nuc_modules`, `nuc_api`, `nuc_stores`, `nuc_globals` |\n| **Auth** | `nuc_users`, `nuc_activity` |\n| **Data** | `nuc_entities` |\n| **UI** | `nuc_templates` (charts, dock, dialog, datatable, sections) |\n| **Visual** | `nuc_globals` (animations), `nuc_colors` |\n| **Layout** | `nuc_pages`, `nuc_templates` |\n\nEach module is self-contained, independently testable, and can be enabled/disabled as needed.\n\n### Feature-Sliced Design\n\nEach module encapsulates all related code within a single directory:\n\n```txt\nmodules/nuc_users/\n├── atomic/                 # Vue/React components & composables\n├── supabase/               # SQL migrations, seeders, API handlers\n│   ├── migrations/\n│   ├── seeders/\n│   └── api/handle.ts\n├── vitests/                # Vitest frontend tests\n└── config.json             # Module metadata\n```\n\n### Override System\n\nThe `nuc_overrides` module provides a powerful customization layer without modifying core code:\n\n```\noverrides/\n├── modules/\n│   └── nuc_settings/       # Override nuc_settings module\n│       ├── components/     # Custom components\n│       └── constants/      # Custom constants\n└── nuxt/\n    └── atomic/             # Override global Nuxt atomic components\n        ├── atom/           # Custom atoms\n        ├── molecule/       # Custom molecules\n        └── organism/       # Custom organisms\n```\n\nOverrides are automatically merged at build time, allowing you to:\n- **Customize UI components** without forking modules\n- **Extend functionality** while preserving upgrade paths\n- **Project-specific modifications** that stay isolated from core code\n- **Update framework freely** - your customizations survive `git pull`\n\n---\n\n## Technology Stack\n\n| Layer | Technologies |\n|-------|-------------|\n| **Backend** | Supabase (PostgreSQL, Auth, Storage), module API gateway |\n| **Frontend** | Nuxt 3 / Next.js, Vue 3 / React, TypeScript, Pinia / Zustand, nucleify-ui |\n| **Styling** | SCSS, GSAP, Chart.js |\n| **DevOps** | Supabase CLI, Vite, Husky, Biome, TSC, Stylelint |\n| **Testing** | Vitest |\n\n---\n\n## Next Steps\n\n1. **[Installation](/en/docs/getting-started/installation)** - Set up your development environment\n2. **[Quick Start](/en/docs/getting-started/quick-start)** - Create your first component\n3. **[Modules](/en/docs/modules/overview)** - Explore available modules\n4. **[Architecture](/en/docs/architecture/overview)** - Deep dive into system design\n",
  "en/getting-started/quick-start": "# Quick Start\n\nGet up and running with Nucleify in minutes.\n\n## Understanding Atomic Design\n\nNucleify uses Atomic Design methodology to organize components:\n\n| Level | Description | Examples |\n|-------|-------------|----------|\n| **Bosons** | Reusable logic, types, utilities | Constants, interfaces, helper functions |\n| **Atoms** | Smallest UI building blocks | Button, Input, Icon, Label |\n| **Molecules** | Simple combinations of atoms | FloatLabel, Anchor, Tile |\n| **Organisms** | Complex UI structures | DataTable, Dialog, Menu, Card |\n\n## Creating Your First Component\n\n### 1. Create the Component Folder\n\nNavigate to the appropriate atomic level in `nuxt/atomic/`:\n\n```txt\nnuxt/atomic/atom/my-component/\n├── index.ts            # Exports\n├── index.vue           # Component\n└── types/\n    ├── index.ts        # Type exports\n    └── interfaces.ts   # Component interfaces\n```\n\n### 2. Define the Interface\n\nCreate your component's type definitions in `types/interfaces.ts`:\n\n```typescript\nexport interface MyComponentInterface {\n  label?: string\n  variant?: 'primary' | 'secondary'\n  disabled?: boolean\n}\n```\n\nExport types in `types/index.ts`:\n\n```typescript\nexport * from './interfaces'\n```\n\n### 3. Build the Component\n\nCreate your Vue component in `index.vue`:\n\n```html\n<template>\n  <div :class=\"$style['my-component']\">\n    {{ props.label }}\n    <slot />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { MyComponentInterface } from '.'\n\nconst props = defineProps<MyComponentInterface>()\n</script>\n\n<style lang=\"scss\" module>\n.my-component {\n  // Your styles\n}\n</style>\n```\n\n### 4. Export the Component\n\nCreate `index.ts` to export everything:\n\n```typescript\nexport { default as AdMyComponent } from './index.vue'\nexport * from './types'\n```\n\n### 5. Register in Parent Index\n\nAdd export to the parent `index.ts` (e.g., `nuxt/atomic/atom/index.ts`):\n\n```typescript\nexport * from './my-component'\n```\n\n## Auto-Import & Registration\n\nComponents in `nuxt/atomic/` are **automatically registered** by Nuxt with the `ad-` prefix. No manual imports needed in templates!\n\n```html\n<template>\n  <!-- These work automatically - no imports required -->\n  <ad-button label=\"Click me\" />\n  <ad-my-component label=\"Hello\" />\n</template>\n\n<script setup lang=\"ts\">\n// No imports needed for template usage!\n</script>\n```\n\n**How it works:**\n- Components from `atom/`, `molecule/`, `organism/` folders are scanned automatically\n- Each component gets the `ad-` prefix (e.g., `button/index.vue` → `<ad-button>`)\n- Types and utilities from `nucleify` alias are also auto-imported\n\n### Explicit Imports\n\nWhen you need to use components or types in script (not template), import from `nucleify`:\n\n```html\n<script setup lang=\"ts\">\nimport { AdButton, type ButtonInterface } from 'nucleify'\n\n// Use in script logic\nconst buttonRef = ref<InstanceType<typeof AdButton>>()\n</script>\n```\n\n### What Gets Auto-Imported\n\n| Source | Auto-Import |\n|--------|-------------|\n| `~/atomic/atom/*` | Components with `ad-` prefix |\n| `~/atomic/molecule/*` | Components with `ad-` prefix |\n| `~/atomic/organism/*` | Components with `ad-` prefix |\n| `~/composables/**` | Composables |\n\n## Styling Components\n\nFor Atomic Design components we recommend using **CSS Modules** - they provide automatic scoping, prevent naming collisions, and work great with TypeScript.\n\n### Option 1: CSS Modules (Recommended)\n\nUse `module` attribute on the style tag. Access classes via `$style` object:\n\n```html\n<template>\n  <div :class=\"$style['my-component']\">\n    <span :class=\"$style.label\">{{ label }}</span>\n  </div>\n</template>\n\n<style lang=\"scss\" module>\n.my-component {\n  display: flex;\n  padding: 1rem;\n\n  .label {\n    font-weight: 600;\n  }\n}\n</style>\n```\n\n**Benefits:**\n- Automatic unique class names (no collisions)\n- TypeScript support via `$style`\n- Better encapsulation for reusable components\n\n### Option 2: Normal SCSS\n\nGlobal styles without scoping. Classes are used directly in template:\n\n```html\n<template>\n  <div class=\"my-component\">\n    <span class=\"label\">{{ label }}</span>\n  </div>\n</template>\n\n<style lang=\"scss\">\n.my-component {\n  display: flex;\n  padding: 1rem;\n\n  .label {\n    font-weight: 600;\n  }\n}\n</style>\n```\n\n**When to use:**\n- Global styles and overrides\n- Styles that need to affect child components\n- Pages and layouts\n\n### External SCSS Files\n\nFor complex components, extract styles to `_index.scss`:\n\n```txt\nmy-component/\n├── _index.scss   # Styles\n├── index.ts\n└── index.vue\n```\n\nImport in your component:\n\n```html\n<style lang=\"scss\">\n@import 'index';\n</style>\n```\n\n## Naming Conventions\n\n| Item | Convention | Example |\n|------|------------|---------|\n| Folder names | kebab-case | `my-component/` |\n| Component exports | PascalCase with `Ad` prefix | `AdMyComponent` |\n| Interfaces | PascalCase with `Interface` suffix | `MyComponentInterface` |\n| CSS classes | kebab-case | `.my-component` |\n| SCSS files | underscore prefix | `_index.scss` |\n\n## Next Steps\n\n- Learn about [Modules](/en/docs/core-concepts/modules) for organizing features\n- Explore [Atomic Design](/en/docs/core-concepts/atomic-design) methodology\n- Read [Code Standards](/en/docs/contributing/code-standards) for best practices\n",
  "en/tests/vitest": "# Vitest (Frontend Testing)\n\nVitest is the frontend testing framework for Vue/TypeScript in Nucleify.\n\n---\n\n## Configuration\n\n### vitest.config.ts\n\n```typescript\nimport { defineVitestConfig } from '@nuxt/test-utils/config'\nimport { resolve } from 'path'\n\nexport default defineVitestConfig({\n  resolve: {\n    alias: {\n      nucleify: resolve(__dirname, 'nuxt/atomic'),\n    },\n  },\n  test: {\n    environment: 'nuxt',\n    setupFiles: ['./vitests/setup.ts'],\n    include: [\n      'vitests/**/*.{test,spec}.{js,ts,jsx,tsx}',\n      'modules/**/*.{test,spec}.{js,ts,jsx,tsx}',\n    ],\n    testTimeout: 30000,\n    pool: 'threads',\n  },\n})\n```\n\n---\n\n## Structure\n\n### Global Tests\n\n```\nvitests/\n├── setup.ts              # Global setup\n├── example.test.ts       # Example test\n└── plugins/              # Plugin tests\n```\n\n### Module Tests\n\n```\nmodules/nuc_example/vitests/\n├── api/\n│   └── User/\n│       └── 200.test.ts\n├── components/\n└── constants/\n    └── api/\n        ├── user.ts\n        └── article.ts\n```\n\n---\n\n## Setup File\n\n### vitests/setup.ts\n\n```typescript\nimport { afterEach } from 'vitest'\n\nconst activeTimeouts = new Set<NodeJS.Timeout>()\nconst activeIntervals = new Set<NodeJS.Timeout>()\n\nconst originalSetTimeout = globalThis.setTimeout\nconst trackedSetTimeout = (callback: Function, delay?: number) => {\n  const id = originalSetTimeout(() => {\n    activeTimeouts.delete(id)\n    callback()\n  }, delay)\n  activeTimeouts.add(id)\n  return id\n}\n\nglobalThis.setTimeout = trackedSetTimeout as typeof setTimeout\n\nafterEach(() => {\n  activeTimeouts.forEach((id) => clearTimeout(id))\n  activeTimeouts.clear()\n  activeIntervals.forEach((id) => clearInterval(id))\n  activeIntervals.clear()\n})\n```\n\n---\n\n## Mocking\n\n### mockGlobalFetch()\n\n```typescript\n// modules/nuc_api/utils/__mocks__/mock_global_fetch.ts\n\nimport type { Mock, vi } from 'vitest'\n\nexport function mockGlobalFetch(\n  vi: { fn: typeof vi.fn; stubGlobal: typeof vi.stubGlobal },\n  response: unknown\n): Mock {\n  const mockFetch: Mock = vi.fn().mockResolvedValue(response)\n  vi.stubGlobal('$fetch', mockFetch)\n  return mockFetch\n}\n```\n\n### Usage\n\n```typescript\nimport { beforeEach, vi } from 'vitest'\nimport * as nucleify from 'nucleify'\n\nbeforeEach((): void => {\n  vi.clearAllMocks()\n  nucleify.mockGlobalFetch(vi, mockResponse)\n})\n```\n\n---\n\n## Mock Data\n\n```typescript\n// vitests/constants/api/user.ts\n\nimport type { NucUserObjectInterface } from 'nucleify'\n\nexport const mockUser: NucUserObjectInterface = {\n  id: 999999,\n  name: 'Test User',\n  email: 'test@example.com',\n  role: 'user',\n  created_at: new Date().toISOString(),\n  updated_at: new Date().toISOString(),\n}\n```\n\n---\n\n## Writing Tests\n\n### Basic Test\n\n```typescript\nimport { expect, test } from 'vitest'\n\ntest('example', (): void => {\n  expect(true).toBe(true)\n})\n```\n\n### API Request Tests\n\n```typescript\nimport { beforeEach, describe, expect, it, type Mock, vi } from 'vitest'\nimport * as nucleify from 'nucleify'\n\ndescribe('userRequests', (): void => {\n  const { closeDialog } = nucleify.useNucDialog()\n  const requests = nucleify.userRequests(closeDialog)\n  const mockResponse = [nucleify.mockUser]\n\n  beforeEach((): void => {\n    vi.clearAllMocks()\n    nucleify.mockGlobalFetch(vi, mockResponse)\n  })\n\n  it('getAllUsers', async (): Promise<void> => {\n    await requests.getAllUsers()\n    expect(\n      (globalThis as unknown as { $fetch: Mock }).$fetch\n    ).toHaveBeenCalledWith(\n      expect.stringContaining('users'),\n      expect.objectContaining({ method: 'GET' })\n    )\n    expect(requests.results.value).toEqual(mockResponse)\n  })\n\n  it('storeUser', async (): Promise<void> => {\n    await requests.storeUser(nucleify.mockUser)\n    expect(\n      (globalThis as unknown as { $fetch: Mock }).$fetch\n    ).toHaveBeenCalledWith(\n      expect.stringContaining('users'),\n      expect.objectContaining({ method: 'POST' })\n    )\n  })\n\n  it('deleteUser', async (): Promise<void> => {\n    await requests.deleteUser(nucleify.mockUser.id ?? 0)\n    expect(\n      (globalThis as unknown as { $fetch: Mock }).$fetch\n    ).toHaveBeenCalledWith(\n      expect.stringContaining('users'),\n      expect.objectContaining({ method: 'DELETE' })\n    )\n  })\n})\n```\n\n### Composable Tests\n\n```typescript\nimport { beforeEach, describe, expect, it, vi } from 'vitest'\nimport * as nucleify from 'nucleify'\n\ndescribe('useAddFriend', (): void => {\n  let instance: ReturnType<typeof nucleify.useAddFriend>\n\n  beforeEach((): void => {\n    vi.clearAllMocks()\n    instance = nucleify.useAddFriend()\n  })\n\n  it('should add friend', async (): Promise<void> => {\n    nucleify.mockGlobalFetch(vi, [{ id: 1, name: 'Test' }])\n    const spy = vi.spyOn(friendship, 'sendRequest')\n\n    await instance.handleAddFriend()\n\n    expect(spy).toHaveBeenCalled()\n  })\n})\n```\n\n### Testing with Spies\n\n```typescript\nimport { describe, expect, it, vi } from 'vitest'\n\ndescribe('spies', (): void => {\n  it('should track calls', (): void => {\n    const callback = vi.fn()\n    callback('arg1', 'arg2')\n    \n    expect(callback).toHaveBeenCalledTimes(1)\n    expect(callback).toHaveBeenCalledWith('arg1', 'arg2')\n  })\n\n  it('should spy on methods', (): void => {\n    const obj = { method: (x: number) => x * 2 }\n    const spy = vi.spyOn(obj, 'method')\n    \n    obj.method(5)\n    \n    expect(spy).toHaveBeenCalledWith(5)\n    expect(spy).toHaveReturnedWith(10)\n  })\n})\n```\n\n---\n\n## Assertions\n\n### Common Matchers\n\n```typescript\n// Equality\nexpect(value).toBe(expected)\nexpect(value).toEqual(expected)\n\n// Truthiness\nexpect(value).toBeTruthy()\nexpect(value).toBeFalsy()\nexpect(value).toBeNull()\nexpect(value).toBeDefined()\n\n// Numbers\nexpect(value).toBeGreaterThan(3)\nexpect(value).toBeLessThan(5)\n\n// Strings\nexpect(value).toMatch(/regex/)\nexpect(value).toContain('substring')\n\n// Arrays/Objects\nexpect(array).toContain(item)\nexpect(array).toHaveLength(3)\nexpect(obj).toHaveProperty('key')\n\n// Functions\nexpect(fn).toHaveBeenCalled()\nexpect(fn).toHaveBeenCalledWith(arg)\nexpect(fn).toHaveBeenCalledTimes(2)\n\n// Async\nawait expect(promise).resolves.toBe(value)\nawait expect(promise).rejects.toThrow(Error)\n\n// Partial matching\nexpect(obj).toMatchObject({ key: 'value' })\nexpect('test').stringContaining('est')\nexpect({ a: 1 }).objectContaining({ a: 1 })\n```\n\n---\n\n## Commands\n\n```bash\n# Run all tests\npnpm run tests\n\n# Watch mode\npnpm run test:watch\n\n# Run once\npnpm run tests\n\n# Specific file\npnpm exec vitest modules/nuc_entities/vitests/api/User/200.test.ts\n\n# With pattern\npnpm exec vitest --filter=\"userRequests\"\n\n# With coverage\npnpm run test:coverage\n\n# With UI\npnpm exec vitest --ui\n\n# Update snapshots\npnpm exec vitest --update\n```\n\n---\n\n## Best Practices\n\n1. **Use `nucleify` alias** - Import from `nuxt/atomic`\n2. **Mock global fetch** - `nucleify.mockGlobalFetch(vi, response)`\n3. **Clear mocks** - `vi.clearAllMocks()` in `beforeEach`\n4. **Use `describe` blocks** - Group related tests\n5. **Keep module tests** in `modules/*/vitests/`\n6. **Test async** with `async/await`\n7. **Use mock data** - Constants in `vitests/constants/`\n8. **Test CRUD** - GET, POST, PUT, DELETE\n9. **Use partial matchers** - `stringContaining()`, `objectContaining()`\n",
  "pl/about/code-of-conduct": "# Kodeks postępowania\n\nNucleify stosuje [Contributor Covenant Code of Conduct 2.1](https://www.contributor-covenant.org/version/2/1/code_of_conduct/).\n\n---\n\n## Nasza deklaracja\n\nDeklarujemy, że uczestnictwo w naszej społeczności będzie wolne od nękania dla wszystkich, niezależnie od wieku, budowy ciała, widocznej lub niewidocznej niepełnosprawności, pochodzenia etnicznego, cech płciowych, tożsamości i ekspresji płciowej, poziomu doświadczenia, wykształcenia, statusu społeczno-ekonomicznego, narodowości, wyglądu osobistego, rasy, kasty, koloru skóry, religii lub orientacji seksualnej.\n\nDeklarujemy działać i współpracować w sposób przyczyniający się do otwartej, przyjaznej, różnorodnej, inkluzywnej i zdrowej społeczności.\n\n---\n\n## Nasze standardy\n\n### Pozytywne zachowania\n\n- Okazywanie empatii i życzliwości\n- Szacunek dla odmiennych opinii\n- Dawanie i przyjmowanie konstruktywnej krytyki\n- Przyjmowanie odpowiedzialności i przepraszanie za błędy\n- Skupianie się na tym, co najlepsze dla społeczności\n\n### Niedopuszczalne zachowania\n\n- Seksualizowany język lub obrazy\n- Trolling, obelgi lub uwłaczające komentarze\n- Publiczne lub prywatne nękanie\n- Publikowanie prywatnych informacji innych osób\n- Inne niestosowne zachowania profesjonalne\n\n---\n\n## Egzekwowanie\n\nLiderzy społeczności będą stosować następujące wytyczne:\n\n### 1. Korekta\n\n**Wpływ**: Niestosowny język lub nieprofesjonalne zachowanie.\n\n**Konsekwencja**: Prywatne pisemne ostrzeżenie z wyjaśnieniem.\n\n### 2. Ostrzeżenie\n\n**Wpływ**: Naruszenie poprzez pojedynczy incydent lub serię działań.\n\n**Konsekwencja**: Ostrzeżenie z konsekwencjami za kontynuowanie zachowania. Brak interakcji z zaangażowanymi stronami przez określony czas.\n\n### 3. Tymczasowy ban\n\n**Wpływ**: Poważne naruszenie, w tym uporczywe niestosowne zachowanie.\n\n**Konsekwencja**: Tymczasowy zakaz interakcji ze społecznością.\n\n### 4. Stały ban\n\n**Wpływ**: Wzorzec naruszeń, nękanie lub agresja.\n\n**Konsekwencja**: Stały zakaz uczestnictwa w społeczności.\n\n---\n\n## Zgłaszanie\n\nZgłaszaj problemy na: **nucleify@gmail.com**\n\nWszystkie skargi będą rozpatrywane szybko i sprawiedliwie. Liderzy społeczności są zobowiązani do poszanowania prywatności i bezpieczeństwa zgłaszających.\n\n---\n\n## Zakres\n\nNiniejszy Kodeks postępowania obowiązuje we wszystkich przestrzeniach społeczności oraz podczas reprezentowania społeczności w przestrzeniach publicznych (oficjalny email, media społecznościowe, wydarzenia).\n\n---\n\n## Atrybucja\n\nZaadaptowano z [Contributor Covenant](https://www.contributor-covenant.org), wersja 2.1.\n\nWytyczne dotyczące wpływu na społeczność zainspirowane [drabiną egzekwowania kodeksu postępowania Mozilli](https://github.com/mozilla/diversity).\n\n\n",
  "pl/about/coding-standards": "# Standardy kodowania\n\nStandardy dla kodu, struktury i nazewnictwa w Nucleify. Przestrzeganie ich zapewnia czytelny, spójny i łatwy w utrzymaniu kod.\n\n---\n\n## Struktura projektu\n\n```txt\nroot/\n├── modules/                # Samowystarczalne moduły (supabase/, atomic/)\n├── nuxt/                   # Frontend Nuxt\n├── next/                   # Frontend Next.js (opcjonalnie)\n├── supabase/               # Scalone SQL, lokalna konfiguracja Supabase\n├── .config/                # Konfiguracja Nuxt/Next/narzędzi\n└── vitests/                # Globalne testy frontendu\n```\n\n---\n\n## Struktura modułu\n\n```txt\nmodules/<nazwa_modulu>/\n├── supabase/               # Migracje, seedery, handlery API\n├── atomic/                 # UI (Vue/React/TS/SCSS)\n├── vitests/                # Testy Vitest\n├── config.json             # Metadane modułu\n├── index.ts                # Barrel export\n├── <nazwa_modulu>.ts       # Rejestracja Vue\n├── <nazwa_modulu>.react.ts # Rejestracja React (opcjonalnie)\n└── README.md\n```\n\n---\n\n## Konwencje nazewnictwa\n\n### Backend (Supabase)\n\n| Typ | Konwencja | Przykład |\n|-----|-----------|----------|\n| Foldery modułów | `snake_case` | `nuc_users`, `nuc_entities` |\n| Migracje SQL | Prefiks timestamp | `20260501000000_nuc_users.sql` |\n| Handlery API | `snake_case` | `handle.ts` w `supabase/api/` |\n| Routy API | `kebab-case` w URL | `/api/user-profile` |\n\n### Frontend (Nuxt/Vue/TypeScript)\n\n| Typ | Konwencja | Przykład |\n|-----|-----------|----------|\n| Komponenty Vue | foldery `kebab-case` | `input-text/index.vue` |\n| Pliki TypeScript | `snake_case` | `use_auth.ts` |\n| Definicje typów | `PascalCase` | `UserProps`, `ButtonEmits` |\n| Composables | prefix `use` | `useAuth.ts` |\n| Stałe | `SCREAMING_SNAKE_CASE` | `API_BASE_URL` |\n| Entry points | `index.ts` / `index.vue` | Główny plik komponentu |\n\n---\n\n## Hierarchia Atomic Design\n\n1. **Boson** – Funkcje narzędziowe, helpery\n2. **Atom** – Podstawowe elementy UI (Button, Input, Icon)\n3. **Molecule** – Połączone atomy (FloatLabel, Anchor)\n4. **Organism** – Złożone komponenty (DataTable, Dialog)\n5. **Template** – Layouty stron (DashboardLayout)\n\n### Struktura komponentu\n\n```txt\n<komponent>/\n├── index.vue               # Główny komponent\n├── index.ts                # Eksporty\n├── _index.scss             # Style (opcjonalnie)\n└── types/\n    ├── index.ts\n    ├── interfaces.ts\n    └── variables.ts\n```\n\n---\n\n## Zasady kodowania\n\n### Ogólne\n\n- Preferuj **czytelność** nad spryt\n- Stosuj **KISS** – Keep It Simple\n- Stosuj **DRY** – Don't Repeat Yourself\n- Komentuj tylko gdy intencja jest niejasna\n- Usuwaj nieużywany kod\n- Trzymaj funkcje małe i skupione\n\n### TypeScript\n\n```typescript\n// ✅ Dobrze - jawne typy\ninterface UserData {\n  id: number\n  name: string\n  email: string\n}\n\nfunction getUser(id: number): UserData {\n  // ...\n}\n\n// ❌ Źle - unikaj any\nfunction getUser(id: any): any {\n  // ...\n}\n```\n\n### Handlery API (TypeScript)\n\n```typescript\n// ✅ Dobrze - typowany wynik handlera\nexport async function handle(ctx: ApiContext): Promise<ApiHandlerResult> {\n  const crud = await trySimpleCrud(ctx)\n  if (crud.handled) return crud\n  return apiNotHandled()\n}\n```\n\n### Vue\n\n```vue\n<script setup lang=\"ts\">\n// ✅ Dobrze - Composition API z TypeScript\ninterface Props {\n  label: string\n  disabled?: boolean\n}\n\nconst props = defineProps<Props>()\nconst emit = defineEmits<{\n  click: []\n}>()\n</script>\n```\n\n---\n\n## Wytyczne dla modułów\n\n- Każdy moduł powinien być **samowystarczalny**\n- Logika backendowa w `modules/<modul>/supabase/`\n- Frontend w `modules/<modul>/ (constants, types, utils, components)`\n- Globalne komponenty w `nuxt/atomic/`\n- Używaj `config.json` dla metadanych\n- Dokumentuj w `README.md`\n\n---\n\n## Dlaczego te standardy\n\n- Zgodność z wzorcami Nuxt, Next i Supabase\n- Umożliwia skalowanie horyzontalne z modułami\n- Jasne rozdzielenie backend/frontend\n- Spójne UI z Atomic Design\n- Łatwe wdrażanie nowych kontrybutorów\n\n\n",
  "pl/about/people-and-credits": "# Ludzie i podziękowania\n\nOsoby i projekty, które umożliwiają istnienie Nucleify.\n\n---\n\n## Główny zespół\n\n### Maintainerzy\n\nOsoby odpowiedzialne za rozwój i kierunek Nucleify.\n\n| Imię | Rola | GitHub |\n|------|------|--------|\n| Szymon Radomski | Creator & Lead | [@szymcode](https://github.com/szymcode) |\n\n---\n\n## Kontrybutorzy\n\nDziękujemy wszystkim, którzy przyczynili się do Nucleify!\n\n| Name | GitHub |\n|------|--------|\n| Mścibor Srebrny | [@Mmesek](https://github.com/Mmesek) |\n| Katarzyna Śmierzchalska | [@KatarzynaS97](https://github.com/KatarzynaS97) |\n| Damian Kamyszek | [@K4mD4m](https://github.com/K4mD4m) |\n| Marcin Fuks | [@J0jeQ](https://github.com/J0jeQ) |\n| Jakub Malik | [@JakubMalik](https://github.com/JakubMalik) |\n| Kacper Bujak | [@kbujak09](https://github.com/kbujak09) |\n| – | [@karol199393](https://github.com/karol199393) |\n| Dominika Zalewska | [@domizalewska](https://github.com/domizalewska) |\n| Kamil Błoński | [@kbloski](https://github.com/kbloski) |\n| – | [@Kacper658](https://github.com/Kacper658) |\n| – | [@pysifu](https://github.com/pysifu) |\n\nWszyscy kontrybutorzy są wymienieni na naszej stronie [GitHub Contributors](https://github.com/nucleify/nucleify/graphs/contributors).\n\n---\n\n## Zbudowane z\n\nNucleify jest zbudowany na bazie niesamowitych projektów open source:\n\n### Backend i dane\n\n| Projekt | Opis |\n|---------|------|\n| [Supabase](https://supabase.com) | PostgreSQL, Auth, Storage, Edge Functions |\n| [@supabase/supabase-js](https://github.com/supabase/supabase-js) | Klient JavaScript |\n\n### Frontend\n\n| Projekt | Opis |\n|---------|------|\n| [Nuxt](https://nuxt.com) | Framework Vue.js |\n| [Vue.js](https://vuejs.org) | Framework JavaScript |\n| [nucleify-ui](https://www.npmjs.com/package/nucleify-ui) | Biblioteka komponentów Lit (`nui-*`) |\n| [Vitest](https://vitest.dev) | Framework testowy |\n\n### Narzędzia\n\n| Projekt | Opis |\n|---------|------|\n| [Vite](https://vitejs.dev) | Narzędzie budowania |\n| [TypeScript](https://www.typescriptlang.org) | Bezpieczeństwo typów |\n| [SCSS](https://sass-lang.com) | Preprocesor CSS |\n| [ESLint](https://eslint.org) | Linting JavaScript |\n| [Biome](https://biomejs.dev) | Formatowanie i linting |\n\n---\n\n## Inspiracje\n\nProjekty i zasoby, które zainspirowały Nucleify:\n\n- [Moduły Nucleify](/pl/docs/core-concepts/modules) – Architektura modułowa\n- [Feature-Sliced Design](https://feature-sliced.design) – Architektura frontend\n- [Atomic Design](https://atomicdesign.bradfrost.com) – Hierarchia komponentów\n\n---\n\n## Specjalne podziękowania\n\n- Społeczności Supabase, Vue.js i React\n- Wszystkim, którzy zgłosili błędy lub zasugerowali funkcje\n- Maintainerom open source na całym świecie\n\n---\n\n## Chcesz pomóc?\n\nZapraszamy do wszelkiego rodzaju wkładów:\n\n- 🐛 Zgłoszenia błędów\n- 💡 Sugestie funkcji\n- 📝 Ulepszenia dokumentacji\n- 🔧 Wkłady kodowe\n\nZobacz nasze [Standardy kodowania](/pl/docs/about/coding-standards), aby zacząć.\n\n---\n\n## Licencja\n\nNucleify jest oprogramowaniem open source na licencji [MIT](https://opensource.org/licenses/MIT).\n\n\n",
  "pl/about/philosophy": "# Filozofia\n\n> *\"Przestań wynajdywać koło na nowo. Zacznij budować swój produkt. Teraz!\"*\n\nPodstawowe zasady, wartości i wizja stojące za Nucleify.\n\n---\n\n## Wizja\n\nNucleify istnieje, ponieważ **nowoczesny development webowy jest niepotrzebnie skomplikowany**. Deweloperzy spędzają tygodnie na konfiguracji narzędzi, miesiące na odtwarzaniu tych samych funkcji i lata na rozplątywaniu monolitycznych baz kodu. Wierzymy, że jest lepszy sposób.\n\nNucleify jest zaprojektowany jako **fundament, którego zawsze potrzebowałeś** – modularny, skalowalny, wydajny i piękny. Framework, który pozwala skupić się na tym, co ważne: **budowaniu Twojego produktu**.\n\n---\n\n## Metafora jądra\n\nJak jądro komórki, Nucleify służy jako **centralne centrum dowodzenia** Twojej aplikacji. Każdy moduł jest samodzielną jednostką z własnym DNA – kompletny, funkcjonalny i zdolny do niezależnego istnienia, jednocześnie przyczyniając się do większego organizmu.\n\nTo nie tylko branding. To architektura:\n\n- **Samodzielne moduły** – Każda funkcja jest kompletna sama w sobie\n- **Jasne granice** – Moduły komunikują się przez zdefiniowane interfejsy\n- **Organiczny wzrost** – Dodawaj lub usuwaj moduły bez psucia systemu\n- **Kolektywna siła** – Razem moduły tworzą coś większego\n\n---\n\n## Podstawowe zasady\n\n### 1. Modularność jest bezdyskusyjna\n\n> *\"Sekretem budowania dużych aplikacji jest nigdy nie budować dużych aplikacji.\"* – Justin Meyer\n\nWszystko w Nucleify jest modułem. Nie dlatego, że to modne, ale dlatego, że działa:\n\n| Korzyść | Dlaczego to ważne |\n|---------|-------------------|\n| **Izolacja** | Zmieniaj jeden moduł bez obaw o zepsucie innych |\n| **Reużywalność** | Używaj tego samego modułu w wielu projektach |\n| **Skalowalność** | Dodawaj funkcje bez wykładniczej złożoności |\n| **Testowalność** | Testuj moduły niezależnie z pewnością |\n| **Prędkość zespołu** | Zespoły posiadają moduły, nie pliki rozrzucone wszędzie |\n\n### 2. Full-Stack Unity\n\nBackend i frontend należą razem. W Nucleify każdy moduł zawiera oba:\n\n```txt\nmodules/nuc_users/\n├── supabase/           # Migracje, seedery, handlery API\n├── atomic/             # Nuxt / Next UI\n└── vitests/            # Testy Vitest\n```\n\nKoniec z przełączaniem kontekstu między repozytoriami. Koniec z niejasnościami kontraktu API. **Jeden moduł, jedna funkcja, jedna prawda.**\n\n### 3. Konwencja ponad konfiguracją\n\nPrzestrzegamy konwencji Nuxt, Next i Supabase. Dlaczego?\n\n- **Zero zmęczenia decyzyjnego** – Skup się na budowaniu, nie konfigurowaniu\n- **Natychmiastowa znajomość** – Deweloperzy full-stack czują się jak w domu\n- **Mądrość społeczności** – Sprawdzone wzorce zamiast wymyślania na nowo\n- **Przewidywalna struktura** – Znajdź dowolny plik w sekundy\n\n### 4. Wydajność domyślnie\n\nNucleify dostarcza **94+ punktów PageSpeed** od razu:\n\n- SSR i Prerendering z inteligentną hydratacją\n- Atomic Design umożliwia chirurgiczny code-splitting\n- Optymalizacja fontów przez `@nuxtjs/google-fonts`\n- Lazy-loading obrazów i optymalizacja formatów\n- Odroczone ładowanie treści przez `nui-deferred-content`\n- Buildy Vite z optymalnym chunkingiem\n\n**Wydajność nie jest dodatkiem. Jest wbudowana.**\n\n### 5. Developer Experience przede wszystkim\n\nŚwietne DX to nie luksus – to mnożnik:\n\n- `make` – Jedna komenda, by uruchomić wszystko\n- Jasne komunikaty błędów wskazujące rozwiązania\n- Hot reload, który naprawdę działa\n- Type safety przez cały stack\n- Dokumentacja szanująca Twój czas\n\n---\n\n## Filozofia jakości\n\n### Jakość kodu\n\n> *\"Zawsze koduj tak, jakby osoba, która kończy utrzymywać Twój kod, była brutalnym psychopatą, który wie gdzie mieszkasz.\"* – John Woods\n\n- **Czytelność ponad spryt** – Kod jest czytany 10x częściej niż pisany\n- **Jawność ponad domniemanie** – Bez magii, bez niespodzianek\n- **Małe, skupione funkcje** – Jedna funkcja, jedno zadanie\n- **Znaczące nazwy** – `getUserById()` nie `get()`\n- **Typuj wszystko** – TypeScript w całym stacku\n\n### Filozofia testowania\n\n- **Testuj zachowanie, nie implementację** – Co robi, nie jak\n- **Wysokie pokrycie dla krytycznych ścieżek** – Auth, płatności, integralność danych\n- **Szybkie, niezawodne testy** – Wolne testy nie są uruchamiane\n- **Vitest** – Testy frontendu i composables\n\n### Filozofia dokumentacji\n\n- **Dokumentuj \"dlaczego\"** – Kod pokazuje \"co\", docs wyjaśniają \"dlaczego\"\n- **Trzymaj docs blisko kodu** – README.md w każdym module\n- **Aktualizuj ze zmianami** – Nieaktualne docs są gorsze niż ich brak\n- **Szanuj czas dewelopera** – Zwięźle, skanowalnie, wykonalnie\n\n---\n\n## Wartości open source\n\n### Transparentność\n\nDevelopment dzieje się otwarcie. Decyzje są dokumentowane. Roadmapy są publiczne. Bez czarnych skrzynek.\n\n### Inkluzywność\n\nKażdy wkład ma znaczenie:\n- 🐛 Zgłoszenia błędów poprawiają jakość\n- 💡 Sugestie funkcji kształtują kierunek\n- 📝 Dokumentacja pomaga wszystkim\n- 🔧 Wkłady kodowe budują funkcje\n\n### Współpraca\n\nBudujemy razem. Code review to okazje do nauki. Dyskusje są pełne szacunku. Każdy ma głos.\n\n### Szacunek\n\nCzas jest cenny. Nie marnujemy Twojego na:\n- Niepotrzebną złożoność\n- Słabą dokumentację\n- Breaking changes bez ścieżek migracji\n- Gatekeeping wkładów\n\n---\n\n## Przyszłość\n\nNucleify ewoluuje poprzez:\n\n- **Feedback społeczności** – Ty kształtujesz roadmapę\n- **Ciągłe udoskonalanie** – Regularne refaktoryzacje, nigdy stagnacja\n- **Przyjmowanie najlepszych praktyk** – Uczenie się z ekosystemu\n- **Utrzymywanie kompatybilności** – Aktualizacje nie powinny psuć Twojej aplikacji\n\n> *\"Jedyną stałą rzeczą jest zmiana.\"* – Heraklit\n\nAle niektóre rzeczy nigdy się nie zmieniają: **modularność, wydajność, developer experience i szacunek dla Twojego czasu.**\n\n---\n\n## Mindset\n\nPodejście, które napędza każdą linijkę kodu w Nucleify:\n\n> *\"Człowiek niewiele uczący się starzeje się jak wół; tylko jego ciało rośnie, ale nie mądrość.\"* \\\n> ~ Siddhartha Gautama\n\nNigdy nie przestawaj się uczyć. Technologia ewoluuje – my też musimy.\n\n> *\"Kto ma powód, by żyć, zniesie niemal każde jak.\"* \\\n> ~ Friedrich Nietzsche\n\nCel napędza wytrwałość. Wiedz, dlaczego budujesz, a przeszkody staną się rozwiązywalne.\n\n> *\"Nie życz sobie, żeby było łatwiej. Życz sobie, żebyś był lepszy.\"* \\\n> ~ Jim Rohn\n\nZłożoność jest nieunikniona. Rozwijaj umiejętności zamiast unikać wyzwań.\n\n> *\"Strach nigdy nie osiągnął najwyższego celu.\"* \\\n> ~ Bô Yin Râ\n\nNie bój się refaktoryzacji, nowych technologii ani ambitnych zmian. Odwaga w kodzie prowadzi do przełomów.\n\n> *\"Nawet idea odpoczynku niepokoi mój umysł.\"*\n\nPasja napędza doskonałość. Buduj, bo nie możesz nie budować.\n\n---\n\nBuduj z celem. Wdrażaj z pewnością.\n\n---\n\n## Dołącz do nas\n\n**Buduj nowocześnie. Skaluj bez wysiłku. Wdrażaj z pewnością.**\n\nBudujemy coś niesamowitego. [Dołącz do nas.](https://github.com/nucleify/nucleify)\n\n",
  "pl/configuration/environment": "# Zmienne środowiskowe\n\nNucleify odczytuje konfigurację z `.env` w katalogu głównym repozytorium. Użyj `.config/.env.nuxt.example` lub `.config/.env.next.example` jako szablonu (`make nuxt` / `make next` kopiuje go automatycznie).\n\nKonfiguracja Nuxt znajduje się w `.config/nuxt/` i jest scalana w `.config/nuxt.config.ts`.\n\n## Wymagane (Supabase)\n\n| Zmienna | Opis | Przykład |\n|---------|------|----------|\n| `SUPABASE_URL` | URL projektu Supabase | `https://xxx.supabase.co` |\n| `SUPABASE_KEY` | Klucz anon/public (bezpieczny w przeglądarce) | `eyJhbG…` |\n| `SUPABASE_SERVICE_ROLE_KEY` | Klucz service role (tylko serwer) | `eyJhbG…` |\n\nNigdy nie udostępniaj `SUPABASE_SERVICE_ROLE_KEY` w bundle klienta ani publicznych repozytoriach.\n\n## Aplikacja\n\n| Zmienna | Opis | Domyślnie |\n|---------|------|-----------|\n| `APP_NAME` | Nazwa aplikacji | `Nucleify` |\n| `APP_ENV` | Środowisko | `local` |\n| `APP_DEBUG` | Szczegółowe błędy | `true` |\n| `APP_FRONTEND` | Aktywny stack | `nuxt` lub `next` |\n| `NUXT_PUBLIC_APP_URL` | Publiczny URL (Nuxt) | `http://localhost:3000` |\n\n## SSR i prerendering (Nuxt)\n\n```env\nSSR=true\nPRERENDER_ROUTES=/home,/dev,/login,/docs\nPRERENDER_CRAWL_LINKS=true\nPRERENDER_IGNORE=/settings\nPRERENDER_LOCALES=en,pl,vn\nNITRO_PRESET=cloudflare\n```\n\n| Zmienna | Opis |\n|---------|------|\n| `SSR` | Włącz server-side rendering |\n| `PRERENDER_ROUTES` | Trasy do prerenderowania (przecinek) |\n| `PRERENDER_CRAWL_LINKS` | Odkrywanie linków podczas prerender |\n| `PRERENDER_IGNORE` | Trasy do pominięcia |\n| `NITRO_PRESET` | Cel wdrożenia Nitro |\n\n## Opcjonalne\n\n| Zmienna | Opis |\n|---------|------|\n| `SUPABASE_EDGE_BASE` | Bazowy URL Edge Functions |\n| `NUC_CONVERT_DOCUMENTS_URL` | Zewnętrzny serwis konwersji dokumentów |\n| `DEV_TOOLS` | Włącz Nuxt devtools |\n\n## Przykład `.env` (Nuxt)\n\n```env\nAPP_NAME=Nucleify\nAPP_ENV=local\nAPP_DEBUG=true\nNUXT_PUBLIC_APP_URL=http://localhost:3000\n\nSUPABASE_URL=https://your-project.supabase.co\nSUPABASE_KEY=your-anon-key\nSUPABASE_SERVICE_ROLE_KEY=your-service-role-key\n\nAPP_FRONTEND=nuxt\nSSR=true\nNITRO_PRESET=cloudflare\n```\n\nZobacz [konfigurację Supabase](/pl/docs/configuration/supabase), aby dowiedzieć się, jak te klucze są używane w bramce API i kliencie.\n",
  "pl/configuration/nuxt": "# Konfiguracja Nuxt\n\nKonfiguracja frontendu w `.config/nuxt.config.ts`, reeksportowana z root `nuxt.config.ts`.\n\n## SSR i Prerendering\n\n```typescript\nssr: process.env.SSR === 'true',\nnitro: {\n  prerender: {\n    routes: process.env.PRERENDER_ROUTES?.split(',') || [],\n    crawlLinks: process.env.PRERENDER_CRAWL_LINKS === 'true',\n    ignore: process.env.PRERENDER_IGNORE?.split(',') || [],\n  },\n  output: { publicDir: './public/build' },\n  minify: true,\n  compressPublicAssets: true,\n},\n```\n\n| Opcja | Opis |\n|-------|------|\n| `ssr` | Włącz server-side rendering |\n| `prerender.routes` | Trasy do prerenderowania przy buildzie |\n| `prerender.crawlLinks` | Auto-odkrywanie linków |\n| `prerender.ignore` | Trasy do pominięcia |\n| `minify` | Minifikacja outputu |\n| `compressPublicAssets` | Kompresja Gzip/Brotli |\n\n## Struktura katalogów\n\n```typescript\nsrcDir: 'nuxt',\npublicDir: './public',\n```\n\n| Opcja | Ścieżka | Opis |\n|-------|---------|------|\n| `srcDir` | `nuxt/` | Pliki źródłowe Nuxt |\n| `publicDir` | `public/` | Statyczne assety |\n\n## Komponenty\n\n```typescript\ncomponents: [\n  { path: '~/atomic/atom', prefix: 'ad', extensions: ['vue'] },\n  { path: '~/atomic/molecule', prefix: 'ad', extensions: ['vue'] },\n  { path: '~/atomic/organism', prefix: 'ad', extensions: ['vue'] },\n]\n```\n\nKomponenty auto-rejestrowane z prefixem `ad-`:\n- `<ad-button>`, `<ad-input-text>`, `<ad-card>`, `<ad-dialog>`\n\n## Auto-importy\n\n```typescript\nimports: {\n  dirs: ['~/composables/**', '~/atomic/**', 'modules/**'],\n},\nalias: {\n  nucleify: '~/atomic',\n},\n```\n\nWszystkie eksporty z tych katalogów są auto-importowane. Użyj aliasu `nucleify`:\n\n```typescript\nimport { useAuth, type UserInterface } from 'nucleify'\n```\n\n## Runtime Config\n\n```typescript\nruntimeConfig: {\n  public: {\n    appUrl: process.env.APP_URL,\n    apiUrl: process.env.API_URL,\n    appEnv: process.env.APP_ENV,\n  },\n},\n```\n\nDostęp w komponentach:\n\n```typescript\nconst config = useRuntimeConfig()\nconst apiUrl = config.public.apiUrl\n```\n\n## App Head\n\n```typescript\napp: {\n  head: {\n    htmlAttrs: { lang: 'en' },\n    title: 'Nucleify - Modular Web Framework',\n    meta: [\n      { charset: 'utf-8' },\n      { name: 'viewport', content: 'width=device-width, initial-scale=1' },\n      { name: 'description', content: '...' },\n    ],\n    link: [\n      { rel: 'icon', type: 'image/x-icon', href: '/favicon.ico' },\n    ],\n  },\n},\n```\n\n## UI (`nucleify-ui`)\n\nKomponenty Lit (`nui-*`) rejestruje plugin `nuxt/plugins/nucleify-ui.client.ts` (`applyTheme`, style globalne). Custom elements `nui-` są ustawione w Vite (`isCustomElement`).\n\n## Vite Build\n\n```typescript\nvite: {\n  build: {\n    chunkSizeWarningLimit: 1600,\n    minify: 'terser',\n    cssCodeSplit: true,\n    rollupOptions: {\n      maxParallelFileOps: 2,\n      output: {\n        manualChunks: {\n          vue: ['vue', 'vue-router', '@unhead/vue'],\n          pinia: ['pinia', 'pinia-plugin-persistedstate'],\n          chartjs: ['chart.js'],\n          gsap: ['gsap'],\n          marked: ['marked'],\n        },\n      },\n    },\n  },\n  optimizeDeps: {\n    include: ['vue', 'vue-router'],\n  },\n},\n```\n\nRęczne chunki dla optymalnego code splitting i cache. Stan: **Pinia** (Nuxt) z `pinia-plugin-persistedstate`; **Zustand** (Next.js) przez `nuc_stores`.\n\n## SCSS\n\n```typescript\nvite: {\n  css: {\n    preprocessorOptions: {\n      scss: {\n        additionalData: `@import \"~/assets/index\";`,\n        silenceDeprecations: ['mixed-decls', 'import', 'color-functions', 'global-builtin'],\n      },\n    },\n  },\n},\n```\n\nGlobalne importy SCSS dostępne we wszystkich komponentach.\n\n## Google Fonts\n\n```typescript\ngoogleFonts: {\n  families: {\n    Inter: '300..700',\n    Nunito: '300..700',\n  },\n  display: 'swap',\n  subsets: ['latin'],\n},\n```\n\n## Ikony\n\n```typescript\nicon: {\n  prefix: 'i-prime',\n  mode: 'css',\n},\n```\n\nUżyj ikon z prefixem `i-prime`:\n\n```html\n<Icon name=\"i-prime:check\" />\n```\n\nDostępne pod `http://localhost:6006` po odpaleniu Nuxta.\n\n## Supabase Auth\n\n```typescript\n// runtimeConfig.public — SUPABASE_URL, SUPABASE_KEY\n```\n\nAutentykacja przez **Supabase Auth** (sesje JWT). Klient konfigurowany w `nuc_client` / `getSupabaseClient()`.\n\n## Experimental\n\n```typescript\nexperimental: {\n  payloadExtraction: true,\n  renderJsonPayloads: true,\n},\n```\n\nOptymalizacje wydajności dla obsługi payloadu.\n\n## Vitalizer\n\n```typescript\nvitalizer: {\n  disableStylesheets: 'entry',\n},\n```\n\nOpóźnia ładowanie niekrytycznego CSS dla lepszych Core Web Vitals.\n",
  "pl/configuration/supabase": "# Konfiguracja Supabase\n\nNucleify używa **Supabase** jako backendu: **PostgreSQL** do danych, **Auth** do użytkowników, **Storage** do plików oraz opcjonalnie **Edge Functions**. Frontend komunikuje się z **bramką API modułów** na trasach serwerowych Nuxt/Next, która używa klienta Supabase z **service role**.\n\n---\n\n## Jak to działa\n\n```txt\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                       NUXT 3 / NEXT (frontend + trasy serwerowe)                       │\n│                                                                                        │\n│ ┌────────────────────────┐    ┌────────────────────────┐    ┌────────────────────────┐ │\n│ │     UI Vue / React     │───►│    nuc_api (klient)    │───►│     bramka /api/*      │ │\n│ │     Pinia / Zustand    │───►│    apiRequest, auth    │───►│    (Nitro / Route)     │ │\n│ └────────────────────────┘    └────────────────────────┘    └────────────────────────┘ │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                            │\n                            modules/*/supabase/api/handle.ts\n                               (handlery tras per moduł)\n                                            ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                        SUPABASE                                        │\n│                                                                                        │\n│     ┌────────────────┐  ┌────────────────┐  ┌────────────────┐  ┌────────────────┐     │\n│     │   PostgreSQL   │  │      Auth      │  │    Storage     │  │ Edge Functions │     │\n│     │     + RLS      │  │     (JWT)      │  │   (buckety)    │  │ (opcjonalnie)  │     │\n│     └────────────────┘  └────────────────┘  └────────────────┘  └────────────────┘     │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n```\n\n### Przepływ żądania\n\n1. **Przeglądarka** wywołuje `apiRequest('/api/contacts', …)` z `nuc_api`.\n2. **Trasa serwerowa** `nuxt/server/api/[...slug].ts` (lub odpowiednik w Next) odbiera żądanie.\n3. Tworzony jest klient Supabase z `SUPABASE_SERVICE_ROLE_KEY` (tylko serwer).\n4. Bramka iteruje po **handlerach modułów** (`handleEntitiesApi`, `handleUsersApi`, …). Pierwszy rozpoznający ścieżkę zwraca JSON.\n5. Handlery używają helperów z `nuc_api` (`tryScopedCrud`, `trySimpleCrud`) i wykonują zapytania przez klient JS (`supabase.from('tabela').select()` itd.).\n6. **Auth:** przeglądarka używa klucza anon (`SUPABASE_KEY`) przez `getSupabaseClient()` — np. `supabase.auth.signInWithPassword`, potem profil w `user_profiles`.\n\n### Dlaczego bramka API, a nie tylko RLS z przeglądarki?\n\n- Spójny **kształt REST** dla wszystkich modułów.\n- **Service role** na serwerze — operacje administracyjne bez ujawniania klucza w kliencie.\n- **Walidacja i scope** (`user_id`) w handlerach modułów.\n- Te same handlery na **Nuxt** i **Next**.\n\n---\n\n## Zmienne środowiskowe\n\nSkopiuj `.config/.env.nuxt.example` lub `.config/.env.next.example` do `.env` w katalogu głównym.\n\n| Zmienna | Wymagana | Opis |\n|---------|----------|------|\n| `SUPABASE_URL` | Tak | URL projektu |\n| `SUPABASE_KEY` | Tak | Klucz anon — bezpieczny w przeglądarce |\n| `SUPABASE_SERVICE_ROLE_KEY` | Tak (serwer) | Service role — **tylko serwer** |\n| `SUPABASE_EDGE_BASE` | Opcjonalnie | Bazowy URL Edge Functions |\n| `NUXT_PUBLIC_APP_URL` | Nuxt | Publiczny URL aplikacji |\n\nNuxt udostępnia wartości publiczne przez `runtimeConfig.public` w `.config/nuxt/runtime.ts`:\n\n```typescript\npublic: {\n  supabaseUrl: process.env.SUPABASE_URL || '',\n  supabaseKey: process.env.SUPABASE_KEY || '',\n}\n```\n\nKonfiguracja prywatna (serwer):\n\n```typescript\nsupabaseServiceRoleKey: process.env.SUPABASE_SERVICE_ROLE_KEY || '',\n```\n\nNext odczytuje `NEXT_PUBLIC_SUPABASE_URL` / `NEXT_PUBLIC_SUPABASE_KEY` z fallbackiem do `SUPABASE_*` w `next.config.ts`.\n\n---\n\n## Struktura modułu (`supabase/`)\n\nKażdy moduł z logiką backendową trzyma SQL i handlery obok frontendu:\n\n```txt\nmodules/nuc_example/\n├── config.json\n├── nuc_example.ts              # registerNucExample (Vue)\n├── index.ts                    # barrel\n├── atomic/                     # UI + composables API\n└── supabase/\n    ├── migrations/             # DDL PostgreSQL (*.sql)\n    ├── seeders/                # Dane seed (*.sql)\n    ├── factories/              # Dane demo/test (*.sql)\n    ├── api/\n    │   ├── handle.ts           # export handleExampleApi(ctx)\n    │   └── *_helpers.ts        # nazwy tabel, mapowanie wierszy\n    └── functions/              # Opcjonalne Edge Functions (Deno)\n```\n\n### Rejestracja handlerów API\n\n**Nuxt** — dodaj handler do `nuxt/server/api/[...slug].ts`:\n\n```typescript\nimport { handleExampleApi } from '../../../modules/nuc_example/supabase/api/handle'\n\nconst handlers = [\n  // …istniejące handlery\n  handleExampleApi,\n]\n```\n\n**Next** — zarejestruj w `modules/nuc_api/supabase/api/gateway_dispatch.ts` (`supabaseApiGatewayHandlers`).\n\nKażdy handler otrzymuje `ApiContext`:\n\n```typescript\ntype ApiContext = {\n  event: H3Event          // lub wrapper żądania Next\n  method: string          // GET, POST, PUT, DELETE\n  segments: string[]      // ścieżka po /api/\n  supabase: SupabaseClient\n  ok: (data, extra?) => object\n}\n```\n\nZwróć `apiNotHandled()`, jeśli ścieżka nie należy do modułu; `apiOk(ctx, data)` lub `apiError(status, message)` gdy obsłużysz żądanie.\n\n### Helpery CRUD (`nuc_api`)\n\n| Helper | Zastosowanie |\n|--------|--------------|\n| `trySimpleCrud` | Publiczne tabele, zagnieżdżone ścieżki jak `/api/modules` |\n| `tryScopedCrud` | Wiersze z `user_id` (kontakty, pliki, …) |\n| Własne trasy | `dispatchRoutes` / handlery specyficzne (auth, uploady) |\n\n---\n\n## Migracje i seedery\n\nPliki SQL w `supabase/migrations/` i `supabase/seeders/` per moduł. Repozytorium scala je w jeden plik i stosuje przez Supabase CLI:\n```bash\n# Scal migracje ze wszystkich modułów (sortowanie po nazwie pliku)\nbash .config/bash/merge-module-supabase-sql.sh migrations\n\n# Zastosuj na lokalnym Supabase (wymaga CLI + uruchomionej instancji)\nbash .config/bash/apply-module-migrations.sh\n\n# Seedery\nbash .config/bash/merge-module-supabase-sql.sh seeders\nbash .config/bash/apply-module-sql.sh seeders\n```\n\nWynik merge: `supabase/.temp/merged_migrations.sql`, `merged_seeders.sql`.\n\n**Nazewnictwo:** `YYYYMMDDHHMMSS_nuc_modulename_opis.sql` — ta sama kolejność we wszystkich modułach.\n\n**RLS:** Migracje zwykle włączają `row level security` i polityki. Bramka API używa service role; bezpośredni dostęp klienta z kluczem anon nadal respektuje polityki.\n\n---\n\n## Uwierzytelnianie\n\n- **Rejestracja / logowanie:** `nuc_users` (`auth/`) używa `getSupabaseClient().auth` (email/hasło, sesja JWT).\n- **Profil:** Po auth ładowany jest wiersz `user_profiles` (`getAndSetUser` w `nuc_users/auth`).\n- **Wywołania API:** `apiRequest` wysyła cookies/nagłówki; serwer weryfikuje scope przez uid z Supabase Auth w handlerach.\n- Sesje to **JWT Supabase Auth**.\n\n---\n\n## Klient (`nuc_client`)\n\n```typescript\nimport { getSupabaseClient } from 'nuc_client'\n\nconst supabase = getSupabaseClient()\nconst { data } = await supabase.from('contacts').select('*')\n```\n\n`modules/nuc_api/supabase/client.ts` rozwiązuje URL/klucz z `runtimeConfig` Nuxt lub `process.env` w Next.\n\n---\n\n## Checklist lokalny\n\n1. Utwórz projekt na [supabase.com](https://supabase.com) (lub `supabase start` lokalnie).\n2. Ustaw `SUPABASE_URL`, `SUPABASE_KEY`, `SUPABASE_SERVICE_ROLE_KEY` w `.env`.\n3. Uruchom migracje: `bash .config/bash/apply-module-migrations.sh`\n4. Uruchom seedery: `bash .config/bash/apply-module-sql.sh seeders`\n5. Uruchom frontend: `make nuxt` lub `make next`\n6. Sprawdź bramkę: `GET /api/test` → `{ \"message\": \"Hello World\" }`\n\n---\n\n## Produkcja\n\n- Nigdy nie commituj kluczy **service role**; używaj sekretów CI/hosta.\n- Ustaw `NITRO_PRESET` (np. `cloudflare`) przy wdrożeniu Nuxt; bramka działa jako funkcje serverless.\n- Dopasuj CORS i `NUXT_PUBLIC_APP_URL` do domeny produkcyjnej.\n- Uruchom scalone migracje na produkcyjnej bazie przed deployem.\n",
  "pl/core-concepts/atomic-design": "# Atomic Design\n\nNucleify implementuje metodologię Atomic Design do tworzenia spójnych, skalowalnych i łatwych w utrzymaniu systemów UI.\n\n## Czym jest Atomic Design?\n\nAtomic Design to metodologia stworzona przez Brada Frosta, która rozkłada interfejsy użytkownika na podstawowe elementy składowe. Inspirowana chemią, organizuje komponenty w hierarchię od najmniejszych elementów do kompletnych stron.\n\n**Kluczowe korzyści:**\n- **Spójność** - Komponenty wielokrotnego użytku zapewniają jednolity wygląd\n- **Łatwość utrzymania** - Zmiany propagują się automatycznie przez cały system\n- **Skalowalność** - Łatwe rozszerzanie bez naruszania istniejącej funkcjonalności\n- **Współpraca** - Przejrzysta struktura ułatwia komunikację w zespole\n\n---\n\n## Główna zasada: Brak logiki biznesowej\n\n> **Komponenty Atomic Design NIE MOGĄ zawierać logiki biznesowej.**\n\nKomponenty powinny zawierać tylko funkcjonalność bezpośrednio związaną z ich zachowaniem UI:\n\n| ✅ Dozwolone | ❌ Niedozwolone |\n|-------------|----------------|\n| Walidacja inputów (format, długość) | Zakodowane na sztywno wywołania API |\n| Animacje i przejścia | Bezpośrednie pobieranie danych |\n| Lokalny stan komponentu | Mutacje store |\n| Emitowanie zdarzeń | Zakodowane na sztywno URL-e lub endpointy |\n| Renderowanie oparte na propsach | Sprawdzanie autoryzacji/uwierzytelniania |\n| Funkcje dostępności | Obliczenia specyficzne dla domeny |\n| Konfigurowalne callbacki przez propsy | Nieelastyczne reguły biznesowe |\n| Generyczne handlery zdarzeń | Zakodowana na sztywno konfiguracja |\n\n**Logika biznesowa należy do:**\n- Store'ów (Pinia / Zustand)\n- Composables\n- Serwisów\n\n### Wyjątki\n\nNucleify rozszerza oryginalny Atomic Design o dedykowane moduły, które **mogą zawierać logikę biznesową**:\n\n| Moduł | Przeznaczenie |\n|-------|---------------|\n| `nuc_templates` | Szablony wielokrotnego użytku dla pojedynczych komponentów (karty, formularze, modale) |\n| `nuc_templates` | Sekcje stron z logiką layoutu, obsługą danych, zachowaniem specyficznym dla sekcji |\n| `nuc_pages` | Pełne komponenty stron z wywołaniami API, dostępem do store'ów, regułami biznesowymi |\n\nTe moduły zostały celowo oddzielone od `nuxt/atomic/`, ponieważ służą jako punkty integracji, gdzie UI spotyka się z logiką aplikacji. Izolując logikę biznesową tutaj, wszystkie pozostałe komponenty atomowe pozostają czyste i wielokrotnego użytku.\n\n---\n\n## Hierarchia\n\nNucleify rozszerza oryginalny Atomic Design o dodatkową warstwę zwaną **Bosons** dla typów i narzędzi.\n\n```txt\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                       Bosons                                           │\n│                      Typy, narzędzia, stałe (niewidoczna warstwa)                      │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                        Atoms                                           │\n│                      Podstawowe elementy UI (Button, Input, Icon)                      │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                      Molecules                                         │\n│                    Proste kombinacje atomów (FloatLabel, Tile)                         │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                      Organisms                                         │\n│                    Złożone sekcje UI (DataTable, Dialog, Menu)                         │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                              Templates  (nuc_templates)                                │\n│                   Szablony komponentów (karty, formularze, modale)                     │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                               Sections  (nuc_templates)                                 │\n│                    Sekcje stron z logiką layoutu i obsługą danych                      │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n                                           ▼\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                                 Pages  (nuc_pages)                                     │\n│                 Pełne strony z wywołaniami API, store'ami, regułami                    │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Bosons - Niewidzialna podstawa\n\nBosons to najmniejsze, niepodzielne elementy logiki wielokrotnego użytku. Nie renderują niczego, ale stanowią fundament dla wszystkich komponentów.\n\n**Co należy do Bosons:**\n- Interfejsy i typy TypeScript\n- Czyste funkcje narzędziowe (bez efektów ubocznych)\n- Stałe i enumy\n- Helpery specyficzne dla komponentów\n\n```typescript\n// types/interfaces.ts\nexport interface ButtonInterface {\n  label?: string\n  variant?: 'primary' | 'secondary' | 'danger'\n  disabled?: boolean\n}\n\n// utils/format_date.ts\nexport function formatDate(date: Date): string {\n  return new Intl.DateTimeFormat('en-US').format(date)\n}\n\n// constants/breakpoints.ts\nexport const BREAKPOINTS = {\n  mobile: 768,\n  tablet: 1024,\n  desktop: 1440,\n} as const\n```\n\n---\n\n## Atoms - Podstawowe elementy\n\nAtoms to najmniejsze wizualne komponenty. Nie można ich dalej rozłożyć bez utraty znaczenia.\n\n**Przykłady:** Button, Input, Icon, Label, Badge, Checkbox, Avatar\n\n**Jaka logika jest dozwolona:**\n- Obsługa zdarzeń click/focus/hover\n- Zarządzanie wewnętrznym stanem (np. wartość inputa)\n- Stosowanie warunkowych stylów na podstawie propsów\n- Emitowanie zdarzeń do rodzica\n\n```html\n<template>\n  <button\n    :class=\"[\n      $style['ad-button'],\n      variant && $style[variant],\n    ]\"\n    :disabled=\"disabled\"\n    @click=\"$emit('click', $event)\"\n  >\n    <slot />\n  </button>\n</template>\n\n<script setup lang=\"ts\">\nimport type { ButtonInterface } from './types'\n\ndefineProps<ButtonInterface>()\ndefineEmits<{ click: [event: MouseEvent] }>()\n</script>\n\n<style lang=\"scss\" module>\n.ad-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.75rem 1.5rem;\n  border-radius: 0.5rem;\n  font-weight: 500;\n  cursor: pointer;\n  transition: all 0.2s ease;\n\n  &.primary {\n    background: var(--primary-color);\n    color: white;\n  }\n\n  &.secondary {\n    background: transparent;\n    border: 1px solid var(--border-color);\n  }\n}\n</style>\n```\n\n**Struktura folderów:**\n\n```txt\natomic/atom/button/\n├── index.vue            # Komponent\n├── index.ts             # Eksporty\n├── _index.scss          # Style (opcjonalne)\n└── types/\n    ├── index.ts\n    ├── interfaces.ts\n    └── variables.ts     # Literały typów\n```\n\n---\n\n## Molecules - Proste kombinacje\n\nMolecules łączą atomy w funkcjonalne jednostki. Mają jedną odpowiedzialność i są nadal stosunkowo proste.\n\n**Przykłady:** FloatLabel, Anchor, Tile\n\n**Jaka logika jest dozwolona:**\n- Koordynowanie stanów atomów-dzieci\n- Proste wartości computed\n- Lokalna walidacja (tylko format, nie reguły biznesowe)\n\n```html\n<template>\n  <div :class=\"$style['float-label']\">\n    <ad-input\n      :id=\"inputId\"\n      v-model=\"model\"\n      :placeholder=\"placeholder\"\n    />\n    <ad-label :for=\"inputId\">\n      {{ label }}\n    </ad-label>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { FloatLabelInterface } from './types'\n\nconst props = defineProps<FloatLabelInterface>()\nconst model = defineModel<string>()\nconst inputId = computed(() => props.id || `input-${Math.random()}`)\n</script>\n```\n\n**Kiedy tworzyć molekułę:**\n- Dwa lub więcej atomów zawsze występują razem\n- Kombinacja ma specyficzną logikę interakcji\n- Reprezentuje pojedynczą, spójną funkcję UI\n\n**Struktura folderów:**\n\n```txt\nnuxt/atomic/molecule/\n├── float-label/\n│   ├── index.vue\n│   ├── index.ts\n│   └── types/\n├── anchor/\n├── tile/\n└── index.ts\n```\n\n---\n\n## Organisms - Złożone struktury\n\nOrganisms to złożone sekcje UI składające się z molekuł, atomów lub innych organizmów. Są nadal komponentami **tylko prezentacyjnymi**.\n\n**Przykłady:** DataTable, Dialog, Menu, Card, Accordion, Navbar\n\n**Jaka logika jest dozwolona:**\n- Renderowanie danych przekazanych przez propsy\n- Lokalne filtrowanie/sortowanie dostarczonych danych\n- Zarządzanie stanami otwarte/zamknięte\n- Emitowanie zdarzeń dla akcji użytkownika\n\n**Co NIE jest dozwolone:**\n- Pobieranie danych z API\n- Bezpośredni dostęp do store'ów\n- Walidacja reguł biznesowych\n\n```html\n<template>\n  <div :class=\"$style['data-table']\">\n    <div :class=\"$style.header\">\n      <ad-input\n        v-model=\"searchQuery\"\n        placeholder=\"Search...\"\n      />\n    </div>\n\n    <table>\n      <thead>\n        <tr>\n          <th v-for=\"col in columns\" :key=\"col.field\">\n            {{ col.header }}\n          </th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr v-for=\"row in filteredData\" :key=\"row.id\">\n          <td v-for=\"col in columns\" :key=\"col.field\">\n            {{ row[col.field] }}\n          </td>\n        </tr>\n      </tbody>\n    </table>\n\n    <ad-pagination\n      v-model=\"currentPage\"\n      :total=\"totalPages\"\n      @change=\"$emit('page-change', $event)\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { DataTableInterface } from './types'\n\n// ✓ Propsy dla danych - komponent nic nie pobiera\nconst props = defineProps<DataTableInterface>()\n\n// ✓ Tylko lokalny stan UI\nconst searchQuery = ref('')\nconst currentPage = ref(1)\n\n// ✓ Lokalne filtrowanie - brak logiki biznesowej\nconst filteredData = computed(() =>\n  props.data.filter(row =>\n    Object.values(row).some(v =>\n      String(v).toLowerCase().includes(searchQuery.value.toLowerCase())\n    )\n  )\n)\n\n// ✓ Emituj zdarzenia - rodzic obsługuje logikę biznesową\ndefineEmits<{ 'page-change': [page: number] }>()\n</script>\n```\n\n**Struktura folderów:**\n\n```txt\nnuxt/atomic/organism/\n├── data-table/\n│   ├── index.vue\n│   ├── index.ts\n│   ├── _index.scss\n│   └── types/\n├── dialog/\n├── menu/\n├── card/\n└── index.ts\n```\n\n---\n\n## Templates\n\nTemplates to szablony komponentów wielokrotnego użytku dla kart, formularzy, modali i innych strukturalnych layoutów. Logika biznesowa jest tutaj dozwolona.\n\n**Lokalizacja:** `modules/nuc_templates/`\n\n```html\n<template>\n  <div :class=\"$style['dashboard-template']\">\n    <aside :class=\"$style.sidebar\">\n      <slot name=\"sidebar\" />\n    </aside>\n    <main :class=\"$style.content\">\n      <header>\n        <slot name=\"header\" />\n      </header>\n      <slot />\n    </main>\n  </div>\n</template>\n```\n\n**Struktura folderów:**\n\n```txt\nmodules/nuc_templates/\n├── atomic/\n│   └── templates/\n│       ├── dashboard/\n│       │   ├── index.vue\n│       │   ├── index.ts\n│       │   └── types/\n│       ├── auth/\n│       ├── card/\n│       └── index.ts\n├── config.json\n└── index.ts\n```\n\n---\n\n## Sections\n\nSections to bloki budulcowe na poziomie strony z logiką layoutu i obsługą danych. Komponują szablony i organizmy w znaczące obszary strony.\n\n**Lokalizacja:** `modules/nuc_templates/`\n\n```html\n<template>\n  <section :class=\"$style['hero-section']\">\n    <div :class=\"$style.content\">\n      <ad-heading>{{ title }}</ad-heading>\n      <ad-paragraph>{{ description }}</ad-paragraph>\n      <ad-button @click=\"handleAction\">{{ actionLabel }}</ad-button>\n    </div>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport type { HeroSectionInterface } from './types'\n\n// ✓ Logika biznesowa dozwolona w sekcjach\nconst props = defineProps<HeroSectionInterface>()\n\nconst emit = defineEmits<{ action: [] }>()\n\nfunction handleAction() {\n  // Może zawierać logikę biznesową\n  emit('action')\n}\n</script>\n```\n\n**Struktura folderów:**\n\n```txt\nmodules/nuc_templates/\n├── atomic/\n│   └── sections/\n│       ├── hero/\n│       │   ├── index.vue\n│       │   ├── index.ts\n│       │   └── types/\n│       ├── features/\n│       ├── pricing/\n│       └── index.ts\n├── config.json\n└── index.ts\n```\n\n---\n\n## Pages\n\nPages to miejsce, gdzie **żyje logika biznesowa**. Łączą komponenty UI ze store'ami, API i stanem aplikacji.\n\n| Część | Lokalizacja | Przeznaczenie |\n|-------|-------------|---------------|\n| Definicja route'a | `nuxt/pages/` | Routing Nuxt (minimalny wrapper) |\n| Zawartość strony | `modules/nuc_pages/pages/` | Logika biznesowa + kompozycja komponentów |\n\n**Plik route'a** (`nuxt/pages/dashboard.vue`):\n\n```html\n<template>\n  <nuc-dashboard-page />\n</template>\n```\n\n**Komponent strony** (`modules/nuc_pages/pages/Dashboard/index.vue`):\n\n```html\n<template>\n  <dashboard-template>\n    <template #sidebar>\n      <navigation-menu :items=\"menuItems\" />\n    </template>\n\n    <!-- ✓ Dane przekazane do komponentu prezentacyjnego -->\n    <ad-data-table\n      :data=\"users\"\n      :columns=\"columns\"\n      @page-change=\"handlePageChange\"\n    />\n  </dashboard-template>\n</template>\n\n<script setup lang=\"ts\">\n// ✓ Logika biznesowa żyje tutaj\nconst userStore = useUserStore()\nconst { users, fetchUsers } = userStore\n\n// ✓ Wywołania API w stronach\nonMounted(() => fetchUsers())\n\n// ✓ Handlery logiki biznesowej\nfunction handlePageChange(page: number) {\n  fetchUsers({ page })\n}\n</script>\n```\n\n**Struktura folderów:**\n\n```txt\nmodules/nuc_pages/\n├── pages/\n│   ├── Dashboard/\n│   │   ├── index.vue\n│   │   ├── index.ts\n│   │   └── types/\n│   ├── Home/\n│   ├── Profile/\n│   └── index.ts\n├── config.json\n└── index.ts\n```\n\n---\n\n## Konwencje nazewnictwa komponentów\n\nWszystkie komponenty atomowe używają prefiksu `ad-` (Atomic Design):\n\n| Poziom | Nazewnictwo | Przykład |\n|--------|-------------|----------|\n| Atom | `ad-{nazwa}` | `<ad-button>`, `<ad-icon>` |\n| Molecule | `ad-{nazwa}` | `<ad-float-label>`, `<ad-tile>` |\n| Organism | `ad-{nazwa}` | `<ad-data-table>`, `<ad-dialog>` |\n| Template | `nuc-{moduł}-{nazwa}` | `<nuc-auth-template>` |\n| Page | `nuc-{moduł}-page` | `<nuc-dashboard-page>` |\n\n---\n\n## Najlepsze praktyki\n\n### 1. Utrzymuj komponenty czyste\n\nKomponenty powinny być przewidywalne - te same propsy zawsze produkują ten sam output:\n\n```html\n<!-- ✓ Dobrze: Czysta prezentacja -->\n<ad-user-card :user=\"user\" @follow=\"$emit('follow', user.id)\" />\n\n<!-- ✗ Źle: Efekty uboczne wewnątrz komponentu -->\n<ad-user-card :userId=\"userId\" />  <!-- pobiera użytkownika wewnętrznie -->\n```\n\n### 2. Props w dół, Events w górę\n\nKomponenty otrzymują dane przez propsy i komunikują zmiany przez zdarzenia:\n\n```html\n<!-- Rodzic obsługuje logikę biznesową -->\n<ad-select\n  v-model=\"selectedOption\"\n  :options=\"options\"\n  @change=\"saveToApi\"\n/>\n```\n\n### 3. Pojedyncza odpowiedzialność\n\nKażdy komponent powinien robić jedną rzecz dobrze:\n\n```html\n<!-- ✓ Dobrze: Skoncentrowany komponent -->\n<ad-avatar :src=\"user.avatar\" :size=\"'lg'\" />\n\n<!-- ✗ Źle: Zbyt wiele odpowiedzialności -->\n<user-card-with-avatar-and-actions-and-menu />\n```\n\n### 4. Używaj interfejsów TypeScript\n\nZawsze definiuj interfejsy propsów dla bezpieczeństwa typów:\n\n```typescript\n// types/interfaces.ts\nexport interface CardInterface {\n  title?: string\n  subtitle?: string\n  variant?: CardVariant\n  clickable?: boolean\n}\n\n// types/variables.ts\nexport type CardVariant = 'default' | 'outlined' | 'elevated'\n```\n",
  "pl/core-concepts/feature-sliced-design": "# Feature-Sliced Design\n\nFeature-Sliced Design (FSD) organizuje kod według domeny biznesowej zamiast warstw technicznych. Każdy moduł to samodzielna jednostka z własnym frontendem, backendem, bazą danych i testami.\n\n## Kluczowe zasady\n\n- Jedna funkcjonalność na moduł\n- Eksportuj tylko to co potrzebne przez `index.ts`\n- Małe moduły - dziel gdy potrzeba\n- Testy obok kodu\n\n## Tradycyjna vs Feature-Sliced\n\n```txt\n# ❌ Warstwowa                   # ✅ Domenowa\nsrc/                             modules/\n├── api/                         ├── nuc_users/\n│   ├── auth-handler.ts          │   ├── supabase/api/handle.ts\n│   └── user-handler.ts          │   ├── supabase/migrations/\n├── db/                          │   ├── pages/\n│   └── users.sql                │   └── vitests/\n└── ui/                          └── nuc_entities/\n    └── auth/                        ├── supabase/api/handle.ts\n                                     └── pages/\n```\n\n## Korzyści\n\n| Korzyść | Opis |\n|---------|------|\n| **Wysoka spójność** | Cały powiązany kod w jednym miejscu |\n| **Niskie powiązania** | Moduły niezależne, włącz/wyłącz przez `config.json` |\n| **Jasne granice** | Jawne API przez eksporty `index.ts` |\n| **Skalowalność zespołu** | Zespoły pracują na oddzielnych modułach bez konfliktów |\n| **Łatwe testowanie** | Testy obok kodu który testują |\n\n## Zależności warstw\n\n**Backend (`supabase/`):**\n`api/handle.ts` → helpery → PostgreSQL (migracje, RLS)\n\n**Frontend (`atomic/`):**\npages → templates → bosons (types, utils, constants)\n\n## Importy między modułami\n\n```typescript\nimport { userRequests, type UserInterface } from 'modules/nuc_entities'\n```\n\nWspółdzielone narzędzia w dedykowanych modułach: `nuc_api`, `nuc_globals`, `nuc_stores`\n\n## Szybkie porównanie\n\n| Aspekt | Warstwowa | Feature-Sliced |\n|--------|-----------|----------------|\n| Szukanie kodu | Wiele folderów | Jeden folder |\n| Dodanie funkcji | Dotknij wiele miejsc | Dodaj jeden folder |\n| Usunięcie funkcji | Szukaj rozproszonych plików | Usuń jeden folder |\n",
  "pl/core-concepts/modules": "# Moduły\n\nModuły są główną jednostką organizacyjną w Nucleify. Zamykają powiązaną funkcjonalność w samodzielnych pakietach wielokrotnego użytku, które działają z **Supabase** (SQL + handlery API) oraz **Vue/Nuxt** lub **React/Next** (frontend).\n\n## Konwencja nazewnictwa\n\n| Typ | Prefix | Przykład |\n|-----|--------|----------|\n| Moduły core | `nuc_` | `nuc_users`, `nuc_entities` |\n| Moduły własne | `twoj_prefix_` | `ex_payments`, `my_blog` |\n\nModuły core (`nuc_*`) są utrzymywane przez Nucleify. Moduły własne powinny używać unikalnego prefixu, aby uniknąć konfliktów.\n\n## Struktura modułu\n\n```txt\nmodules/ex_example/\n├── config.json              # Metadane modułu (wymagane)\n├── ex_example.ts            # Rejestracja komponentów Vue\n├── ex_example.react.ts      # Rejestracja React (opcjonalnie)\n├── index.ts                 # Barrel export TypeScript\n├── _index.scss              # Punkt wejścia SCSS\n├── README.md\n├── atomic/                  # Komponenty UI i composables\n├── supabase/                # Backend: SQL + handlery API\n│   ├── migrations/\n│   ├── seeders/\n│   ├── factories/\n│   └── api/handle.ts\n└── vitests/                 # Testy Vitest\n```\n\n## Wymagane pliki\n\n### `config.json`\n\nMetadane i stan modułu:\n\n```json\n{\n  \"name\": \"ex_example\",\n  \"description\": \"Opis przykładowego modułu\",\n  \"version\": \"0.0.1\",\n  \"category\": \"feature\",\n  \"installed\": true,\n  \"enabled\": true\n}\n```\n\n| Pole | Opis |\n|------|------|\n| `name` | Unikalny identyfikator, musi odpowiadać nazwie folderu |\n| `description` | Krótki opis przeznaczenia modułu |\n| `version` | Wersja semantyczna |\n| `category` | `core`, `feature` lub `utility` |\n| `installed` | Czy moduł jest zainstalowany |\n| `enabled` | Czy moduł jest aktywny |\n\n### `ex_example.ts`\n\nGlobalna rejestracja komponentów Vue:\n\n```typescript\nimport type { App } from 'vue'\nimport { ExExamplePage } from './atomic'\n\nexport function registerExExample(app: App<Element>): void {\n  app.component('ex-example-page', ExExamplePage)\n}\n```\n\nZarejestruj w `nuxt/plugins/modules.ts` przez `registerExExample`.\n\n### `supabase/api/handle.ts`\n\nHandler API dla bramki modułu:\n\n```typescript\nimport { apiNotHandled, trySimpleCrud } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleExampleApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  if (ctx.segments[0] !== 'examples') return apiNotHandled()\n  return (await trySimpleCrud(ctx, { table: 'examples' })) ?? apiNotHandled()\n}\n```\n\nDodaj `handleExampleApi` do tablicy handlerów w `nuxt/server/api/[...slug].ts`.\n\n### `index.ts`\n\nBarrel export dla wszystkich eksportów modułu:\n\n```typescript\nexport * from './ex_example'\nexport * from './atomic'\nexport * from './vitests'\n```\n\nDodaj do `modules/index.ts`:\n\n```typescript\nexport * from './ex_example'\n```\n\n## Struktura backendu (`supabase/`)\n\n```txt\nsupabase/\n├── migrations/                     # Schemat PostgreSQL (*.sql)\n├── seeders/                        # Dane seed\n├── factories/                      # Dane demo/testowe\n├── api/\n│   ├── handle.ts                   # Wejście bramki: handleExampleApi\n│   └── *_helpers.ts                # Nazwy tabel, mapowanie wierszy\n└── functions/                      # Opcjonalne Edge Functions\n```\n\nHandlery używają helperów `nuc_api` (`trySimpleCrud`, `tryScopedCrud`) oraz klienta Supabase JS przekazanego w `ApiContext`.\n\n## Struktura frontendu (`atomic/`)\n\nWykorzystuje metodologię Atomic Design:\n\n```txt\natomic/\n├── index.ts                        # Barrel export\n├── _index.scss                     # Importy SCSS\n├── bosons/                         # Narzędzia i typy (najmniejsze jednostki)\n│   ├── constants/                  # Wartości statyczne\n│   │   └── fields/                 # Definicje pól formularzy\n│   ├── types/                      # Interfejsy TypeScript\n│   │   ├── api/                    # Typy odpowiedzi API\n│   │   └── object/                 # Typy obiektów domenowych\n│   └── utils/                      # Funkcje pomocnicze\n│       └── api/                    # Funkcje żądań API\n├── pages/                          # Komponenty pełnych stron\n│   └── General/\n│       ├── index.ts\n│       └── index.vue\n└── templates/                      # Sekcje stron/layouty\n    └── Dashboard/\n        ├── index.ts\n        └── General.vue\n```\n\n### Bosons\n\nNajmniejsze elementy składowe — typy, stałe, narzędzia:\n\n```typescript\n// types/api/interfaces.ts\nexport interface ExampleApiResponse {\n  id: number\n  name: string\n  created_at: string\n}\n\n// utils/api.ts\nexport async function getExamples(): Promise<ExampleApiResponse[]> {\n  return await api.get('/api/examples')\n}\n```\n\n### Pages\n\nKomponenty pełnych stron Vue:\n\n```html\n<!-- pages/General/index.vue -->\n<template>\n  <ExExampleDashboard />\n</template>\n\n<script setup lang=\"ts\">\nimport { ExExampleDashboard } from '../../templates'\n</script>\n```\n\n### Templates\n\nWielokrotnego użytku sekcje stron:\n\n```html\n<!-- components/Dashboard/General.vue -->\n<template>\n  <section class=\"ex-example-dashboard\">\n    <slot />\n  </section>\n</template>\n```\n\n## Baza danych (`supabase/migrations/`)\n\n```txt\nsupabase/migrations/\n└── 20260501000000_nuc_example.sql\n```\n\nZastosuj przez `bash .config/bash/apply-module-migrations.sh` (scala SQL ze wszystkich modułów).\n\n## Trasy API\n\nBramka mapuje `/api/{segments}` na handlery modułów. Przykład: `GET /api/examples` → `handleExampleApi` → `supabase.from('examples').select()`.\n\n## Testowanie\n\n### Vitest (`vitests/`)\n\nTesty jednostkowe frontendu:\n\n```txt\nvitests/\n├── index.ts                        # Barrel export\n├── api/                            # Testy żądań API\n│   └── Example/\n│       └── 200.test.ts\n└── constants/                      # Stałe testowe\n    └── api/\n        └── example.ts\n```\n\n## Tworzenie modułu\n\n1. **Utwórz folder**: `modules/twojprefix_nazwamodulu/`\n\n2. **Dodaj `config.json`** z metadanymi modułu\n\n3. **Utwórz punkty wejścia**:\n   - `twojprefix_nazwamodulu.ts` (Vue) i/lub `.react.ts` (React)\n   - `index.ts` (zawsze wymagane)\n   - `supabase/api/handle.ts` (jeśli potrzebne API)\n\n4. **Zarejestruj moduł**:\n   - Dodaj handler do `nuxt/server/api/[...slug].ts` (i bramki Next, jeśli używana)\n   - Dodaj do `modules/index.ts` i `nuxt/plugins/modules.ts`\n\n5. **Dodaj strukturę** według potrzeb:\n   - `atomic/` dla UI\n   - `supabase/migrations`, `seeders` dla bazy danych\n   - `vitests/` dla testów\n\n## Dobre praktyki\n\n- **Nazewnictwo**: Używaj unikalnego prefixu (`nuc_` jest zarezerwowany dla modułów core)\n- **Eksporty**: Eksportuj wszystko przez pliki `index.ts`\n- **Typy**: Definiuj wszystkie typy TypeScript w `types/`\n- **API**: Trzymaj logikę API w `utils/api.ts`\n- **Testowanie**: Preferuj Vitest dla UI i composables API\n- **SCSS**: Używaj `_index.scss` dla stylów specyficznych dla modułu\n- **Dokumentacja**: Dołącz `README.md` do każdego modułu\n",
  "pl/core-concepts/overriding": "# Nadpisywanie\n\nNadpisywanie pozwala zastąpić oryginalne pliki bez modyfikowania kodu źródłowego. Umożliwia to wdrożenia customowe u klienta bez edytowania plików core, przy zachowaniu czystej ścieżki aktualizacji.\n\nObsługiwane nadpisania:\n- **Frontend** (Vue, TypeScript): `nuxt/`, `modules/*`\n- **Backend** (Supabase SQL, API handlers): `modules/*/supabase/`\n\n## Kluczowe zasady\n\n- Pliki nadpisujące muszą mieć **dokładnie taką samą ścieżkę** jak oryginały\n- Pliki nadpisujące **całkowicie zastępują** oryginały (bez łączenia)\n- Skopiuj oryginalny folder, usuń pliki których nie nadpisujesz, **zostaw tylko te które zmieniasz**\n- Nadpisuj tylko to, co **musisz zmienić**\n- Testuj dokładnie - nadpisania mogą przestać działać po aktualizacjach\n\n## Jak to działa\n\nUmieść pliki w katalogu `overrides/` z taką samą strukturą jak oryginał:\n\n```txt\noverrides/\n├── nuxt/                    # Nadpisania dla katalogu nuxt/\n│   ├── composables/\n│   ├── pages/\n│   └── ...\n└── modules/                 # Nadpisania dla katalogu modules/\n    └── nuc_users/\n        ├── atomic/\n        └── supabase/\n```\n\nSystem automatycznie:\n- **Frontend**: Przekierowuje importy, wyklucza oryginały z buildu, obsługuje wszystkie typy importów\n- **Backend**: Ta sama mechanika dla handlerów `supabase/api/*.ts` importowanych przez bramkę API\n\n## Typowe przypadki użycia\n\n### Własna autentykacja\n\n```txt\noverrides/\n└── modules/\n    └── nuc_users/\n        ├── atomic/\n        │   └── pages/\n        │       └── Login/\n        │           └── index.vue      # Własny UI logowania\n        └── supabase/\n            └── api/\n                └── handle.ts              # Własna logika API\n```\n\n### Własny handler API\n\n```txt\noverrides/\n└── modules/\n    └── nuc_entities/\n        └── supabase/\n            └── api/\n                └── handle.ts           # Dodatkowa walidacja lub zapytania\n```\n\n### Własny dashboard\n\n```txt\noverrides/\n└── nuxt/\n    └── pages/\n        └── dashboard.vue              # Własny layout dashboardu\n```\n\n## Nadpisywanie frontendu\n\n### Komponenty Vue\n\nOryginał: `modules/nuc_users/auth/pages/login.vue`\n\nNadpisanie: `overrides/modules/nuc_users/auth/pages/login.vue`\n\n```html\n<template>\n  <div class=\"custom-login\">\n    <!-- Twój własny UI logowania -->\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n// Twoja własna logika\n</script>\n```\n\n### Pliki TypeScript\n\nOryginał: `nuxt/composables/useAuth.ts`\n\nNadpisanie: `overrides/nuxt/composables/useAuth.ts`\n\n```typescript\nexport function useAuth() {\n  // Twoja własna logika autentykacji\n}\n```\n\n### Strony Nuxt\n\nOryginał: `nuxt/pages/dashboard.vue`\n\nNadpisanie: `overrides/nuxt/pages/dashboard.vue`\n\n## Nadpisywanie backendu\n\n### Handlery API\n\nOryginał: `modules/nuc_users/supabase/api/handle.ts`\n\nNadpisanie: `overrides/modules/nuc_users/supabase/api/handle.ts`\n\n```typescript\nimport { apiNotHandled } from 'nuc_api'\nimport type { ApiContext, ApiHandlerResult } from 'nuc_server'\n\nexport async function handleAuthApi(ctx: ApiContext): Promise<ApiHandlerResult> {\n  // Twoja własna logika handlera\n  return apiNotHandled()\n}\n```\n\n### Migracje SQL\n\nDla zmian schematu specyficznych dla wdrożenia preferuj nowe pliki migracji we własnym module zamiast nadpisywania core SQL. Jeśli musisz nadpisać dane seed, odwzoruj ścieżkę w `overrides/modules/<module>/supabase/seeders/`.\n\n## Szczegóły techniczne\n\n### Frontend (Vite Plugin)\n\nSystem nadpisywania używa pluginu Vite który:\n1. Skanuje `overrides/nuxt/` i `overrides/modules/` przy starcie\n2. Tworzy mapowanie oryginał → ścieżka nadpisania\n3. Przechwytuje ładowanie plików i zwraca zawartość nadpisania\n4. Obserwuje zmiany i hot-reloaduje\n\nHandlery API po stronie serwera w `modules/*/supabase/api/` korzystają z tego samego rozwiązywania ścieżek przy imporcie w buildzie Nuxt/Next.\n",
  "pl/getting-started/installation": "# Instalacja\n\n## Gotowe w mniej niż 5 minut\n\nNucleify to frontend **Nuxt 3** lub **Next.js** z backendem **Supabase**. Jedna komenda `make` kopiuje konfigurację, instaluje zależności i uruchamia serwer deweloperski.\n\n---\n\n## Wymagania\n\n| Wymaganie | Wersja | Komenda |\n|-----------|--------|---------|\n| **Node.js** | 20.x+ | `node --version` |\n| **pnpm** | 9.x+ | `pnpm --version` |\n| **Git** | Najnowszy | `git --version` |\n| **Supabase CLI** | Najnowszy (baza) | `supabase --version` |\n\nPotrzebny jest projekt Supabase ([supabase.com](https://supabase.com)) lub lokalna instancja (`supabase start`).\n\n---\n\n## Instalacja jedną komendą\n\n```bash\ngit clone https://github.com/Nucleify/Nucleify.git\ncd Nucleify\nmake nuxt    # lub: make next\n```\n\n---\n\n## Baza danych\n\nPo uzupełnieniu `.env` kluczami Supabase:\n\n```bash\nbash .config/bash/apply-module-migrations.sh\nbash .config/bash/apply-module-sql.sh seeders\n```\n\n---\n\n## Adresy\n\n| Usługa | URL |\n|--------|-----|\n| **Nuxt** | `http://localhost:3000` |\n| **API** | `http://localhost:3000/api/test` |\n\n---\n\n## Dalej\n\n1. **[Supabase](/pl/docs/configuration/supabase)** — Jak działa backend\n2. **[Szybki start](/pl/docs/getting-started/quick-start)**\n3. **[Moduły](/pl/docs/core-concepts/modules)**\n",
  "pl/getting-started/introduction": "# Wprowadzenie\n\n## Buduj szybciej. Skaluj bez wysiłku. Wdrażaj z pewnością.\n\n**Nucleify** to modularny full-stack framework, który eliminuje chaos współczesnego web developmentu. Jedna komenda do startu. Ponad 40 sprawdzonych modułów gotowych do wdrożenia. Zero nadmiarowej konfiguracji.\n\n> *\"Przestań wymyślać koło na nowo. Zacznij budować swój produkt. Teraz!\"*\n\nNapędzany przez **Supabase** + **Nuxt 3** / **Next.js** — Nucleify to modularna aplikacja full-stack z PostgreSQL, Auth i bramką API modułów.\n\n---\n\n## Czym jest Nucleify?\n\nZa szybkością stoi **modularna architektura inspirowana jądrem atomu** - każda funkcjonalność żyje jako samodzielny, niezależnie testowalny moduł. Koniec z poplątanymi zależnościami. Koniec z \"u mnie działa\". Tylko czysty, przewidywalny kod, który skaluje się wraz z Twoim zespołem i ambicjami.\n\n**Supabase** przechowuje dane i uwierzytelnia użytkowników. **Nuxt 3** lub **Next.js** dostarcza SSR i reaktywny UI. Handlery w `supabase/api/` łączą oba światy przez `/api/*`.\n\n### Liczby\n\n| Metryka | Wartość |\n|---------|---------|\n| **Czas do MVP** | < 5 minut setup |\n| **Dostępność** | Zgodność z WCAG 2.1 AA |\n| **Wynik PageSpeed** | 94/100 |\n| **Wynik SEO** | 100/100 |\n| **Pokrycie testami** | 92% |\n| **Moduły produkcyjne** | 40+ |\n| **Komponenty UI** | 100+ |\n\n### Co otrzymujesz\n\n- **40+ gotowych modułów produkcyjnych** - Auth, pliki, wykresy, datatables, animacje - wszystko wbudowane\n- **Pełne typowanie** - TypeScript w całym stacku = zero niespodzianek w runtime\n- **System Atomic Design** - 100+ komponentów zgodnych z najlepszymi praktykami branży\n- **System Override** - Dostosuj dowolny moduł bez forkowania, zachowaj ścieżki aktualizacji\n- **Setup jedną komendą** - `make` i już działasz\n\n---\n\n## Dlaczego wybrać Nucleify?\n\n| Wyzwanie | ❌ Tradycyjne podejście | ✅ Rozwiązanie Nucleify |\n|----------|-------------------------|-------------------------|\n| **Rosnąca złożoność** | Monolityczny codebase staje się niemożliwy do zarządzania | Samodzielne moduły skalują się niezależnie |\n| **Ponowne użycie kodu** | Kopiuj-wklej między projektami | Moduły są przenośne i współdzielone |\n| **Trudności z testowaniem** | Ściśle powiązany kod trudno testować | Izolowane moduły umożliwiają skupione testy |\n| **Współpraca zespołowa** | Konflikty merge i wzajemne przeszkadzanie | Zespoły są właścicielami konkretnych modułów |\n\n---\n\n## Przegląd architektury\n\nNucleify łączy **frontend** z **Supabase** przez bramkę API modułów:\n\n```txt\n┌────────────────────────────────────────────────────────────────────────────────────────┐\n│                          NUXT 3 / NEXT (frontend + trasy /api)                         │\n│                                                                                        │\n│  ┌────────────────────┐  ┌────────────────────┐  ┌──────────────────────────────────┐  │\n│  │       Pages        │  │      Layouts       │  │        Atomic Components         │  │\n│  │      (Router)      │  │  (Default, Admin)  │  │  (Atoms, Molecules, Organisms)   │  │\n│  └────────────────────┘  └────────────────────┘  └──────────────────────────────────┘  │\n│                                           │                                            │\n│  ┌────────────────────────────────────────▼─────────────────────────────────────────┐  │\n│  │                       ZARZĄDZANIE STANEM PINIA / ZUSTAND                        │  │\n│  └────────────────────────────────────────┬─────────────────────────────────────────┘  │\n│                                           │                                            │\n│  ┌────────────────────────────────────────▼─────────────────────────────────────────┐  │\n│  │              nuc_api — apiRequest, Supabase Auth (klient)                        │  │\n│  └────────────────────────────────────────┬─────────────────────────────────────────┘  │\n└───────────────────────────────────────────┼────────────────────────────────────────────┘\n                                            │  /api/*\n┌───────────────────────────────────────────▼────────────────────────────────────────────┐\n│                       HANDLERY MODUŁÓW (supabase/api/handle.ts)                        │\n│                    Bramka nuc_api — klient Supabase (service role)                     │\n└───────────────────────────────────────────┬────────────────────────────────────────────┘\n                                            │\n┌───────────────────────────────────────────▼────────────────────────────────────────────┐\n│                                    SUPABASE (PostgreSQL)                               │\n│                         Auth · Storage · RLS · Edge Functions                          │\n└────────────────────────────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Podstawowe zasady projektowe\n\n### Atomic Design\n\nKomponenty UI zorganizowane w hierarchiczną strukturę dla maksymalnej wielokrotnego użycia. Wszystkie komponenty używają prefiksu `ad-` (Atomic Design):\n\n| Poziom | Opis | Przykłady |\n|--------|------|-----------|\n| **Boson** | Funkcje użytkowe, stałe, typy | `camelToKebab()`, `API_BASE_URL` |\n| **Atom** | Podstawowe elementy UI | `<ad-button>`, `<ad-input-text>`, `<ad-avatar>` |\n| **Molecule** | Kombinacje atomów | `<ad-float-label>`, `<ad-anchor>`, `<ad-tile>` |\n| **Organism** | Złożone struktury komponentów | `<ad-data-table>`, `<ad-dialog>`, `<ad-chart>` |\n\n### Architektura modularna\n\nNucleify zawiera gotowe moduły produkcyjne zorganizowane według domeny:\n\n| Kategoria | Moduły |\n|-----------|--------|\n| **Core** | `nuc_modules`, `nuc_api`, `nuc_stores`, `nuc_globals` |\n| **Auth** | `nuc_users`, `nuc_activity` |\n| **Data** | `nuc_entities` |\n| **UI** | `nuc_templates` (charts, dock, dialog, datatable, sections) |\n| **Visual** | `nuc_globals` (animations), `nuc_colors` |\n| **Layout** | `nuc_pages`, `nuc_templates` |\n\nKażdy moduł jest samodzielny, niezależnie testowalny i może być włączany/wyłączany w razie potrzeby.\n\n### Feature-Sliced Design\n\nKażdy moduł zawiera cały powiązany kod w jednym katalogu:\n\n```txt\nmodules/nuc_users/\n├── atomic/                 # Komponenty Vue/React i composables\n├── supabase/               # Migracje SQL, seedery, handlery API\n│   ├── migrations/\n│   ├── seeders/\n│   └── api/handle.ts\n├── vitests/                # Testy Vitest (frontend)\n└── config.json             # Metadane modułu\n```\n\n### System nadpisań\n\nModuł `nuc_overrides` zapewnia potężną warstwę nadpisywania bez modyfikacji kodu źródłowego:\n\n```\noverrides/\n├── modules/\n│   └── nuc_settings/       # Nadpisz moduł nuc_settings\n│       ├── components/     # Własne komponenty\n│       └── constants/      # Własne stałe\n└── nuxt/\n    └── atomic/             # Nadpisz globalne komponenty Nuxt atomic\n        ├── atom/           # Własne atomy\n        ├── molecule/       # Własne molekuły\n        └── organism/       # Własne organizmy\n```\n\nNadpisania są automatycznie scalane podczas budowania, co pozwala na:\n- **Dostosowanie komponentów UI** bez forkowania modułów\n- **Rozszerzanie funkcjonalności** zachowując ścieżki aktualizacji\n- **Modyfikacje specyficzne dla projektu** pozostające izolowane od kodu źródłowego\n- **Swobodne aktualizacje frameworka** - Twoje dostosowania przetrwają `git pull`\n\n---\n\n## Stack technologiczny\n\n| Warstwa | Technologie |\n|---------|-------------|\n| **Backend** | Supabase (PostgreSQL, Auth, Storage, Edge Functions) |\n| **Frontend** | Nuxt 3 / Next.js, Vue 3 / React, TypeScript, Pinia / Zustand, nucleify-ui |\n| **Stylowanie** | SCSS, GSAP, Chart.js |\n| **DevOps** | Supabase CLI, Vite, Husky, Biome, TSC, Stylelint |\n| **Testowanie** | Vitest |\n\n---\n\n## Następne kroki\n\n1. **[Instalacja](/pl/docs/getting-started/installation)** - Skonfiguruj środowisko deweloperskie\n2. **[Szybki start](/pl/docs/getting-started/quick-start)** - Stwórz swój pierwszy komponent\n3. **[Moduły](/pl/docs/modules/overview)** - Odkryj dostępne moduły\n4. **[Architektura](/pl/docs/architecture/overview)** - Głębokie zanurzenie w projektowanie systemu\n\n",
  "pl/getting-started/quick-start": "# Szybki Start\n\nZacznij pracę z Nucleify w kilka minut.\n\n## Zrozumienie Atomic Design\n\nNucleify wykorzystuje metodologię Atomic Design do organizacji komponentów:\n\n| Poziom | Opis | Przykłady |\n|--------|------|-----------|\n| **Bosons** | Logika wielokrotnego użytku, typy, narzędzia | Stałe, interfejsy, funkcje pomocnicze |\n| **Atoms** | Najmniejsze elementy UI | Button, Input, Icon, Label |\n| **Molecules** | Proste kombinacje atomów | FloatLabel, Anchor, Tile |\n| **Organisms** | Złożone struktury UI | DataTable, Dialog, Menu, Card |\n\n## Tworzenie Pierwszego Komponentu\n\n### 1. Utwórz Folder Komponentu\n\nPrzejdź do odpowiedniego poziomu atomic w `nuxt/atomic/`:\n\n```txt\nnuxt/atomic/atom/my-component/\n├── index.ts            # Eksporty\n├── index.vue           # Komponent\n└── types/\n    ├── index.ts        # Eksporty typów\n    └── interfaces.ts   # Interfejsy komponentu\n```\n\n### 2. Zdefiniuj Interfejs\n\nUtwórz definicje typów komponentu w `types/interfaces.ts`:\n\n```typescript\nexport interface MyComponentInterface {\n  label?: string\n  variant?: 'primary' | 'secondary'\n  disabled?: boolean\n}\n```\n\nEksportuj typy w `types/index.ts`:\n\n```typescript\nexport * from './interfaces'\n```\n\n### 3. Zbuduj Komponent\n\nUtwórz komponent Vue w `index.vue`:\n\n```html\n<template>\n  <div :class=\"$style['my-component']\">\n    {{ props.label }}\n    <slot />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { MyComponentInterface } from '.'\n\nconst props = defineProps<MyComponentInterface>()\n</script>\n\n<style lang=\"scss\" module>\n.my-component {\n  // Twoje style\n}\n</style>\n```\n\n### 4. Eksportuj Komponent\n\nUtwórz `index.ts` aby wyeksportować wszystko:\n\n```typescript\nexport { default as AdMyComponent } from './index.vue'\nexport * from './types'\n```\n\n### 5. Zarejestruj w Rodzicu Index\n\nDodaj eksport do nadrzędnego `index.ts` (np. `nuxt/atomic/atom/index.ts`):\n\n```typescript\nexport * from './my-component'\n```\n\n## Auto-Import i Rejestracja\n\nKomponenty w `nuxt/atomic/` są **automatycznie rejestrowane** przez Nuxt z prefixem `ad-`. Nie potrzeba ręcznych importów w templateach!\n\n```html\n<template>\n  <!-- Działają automatycznie - bez importów -->\n  <ad-button label=\"Kliknij mnie\" />\n  <ad-my-component label=\"Cześć\" />\n</template>\n\n<script setup lang=\"ts\">\n// Brak importów potrzebnych do użycia w template!\n</script>\n```\n\n**Jak to działa:**\n- Komponenty z folderów `atom/`, `molecule/`, `organism/` są skanowane automatycznie\n- Każdy komponent dostaje prefix `ad-` (np. `button/index.vue` → `<ad-button>`)\n- Typy i narzędzia z aliasu `nucleify` są również auto-importowane\n\n### Jawne Importy\n\nGdy potrzebujesz użyć komponentów lub typów w script (nie template), importuj z `nucleify`:\n\n```html\n<script setup lang=\"ts\">\nimport { AdButton, type ButtonInterface } from 'nucleify'\n\n// Użycie w logice script\nconst buttonRef = ref<InstanceType<typeof AdButton>>()\n</script>\n```\n\n### Co Jest Auto-Importowane\n\n| Źródło | Auto-Import |\n|--------|-------------|\n| `~/atomic/atom/*` | Komponenty z prefixem `ad-` |\n| `~/atomic/molecule/*` | Komponenty z prefixem `ad-` |\n| `~/atomic/organism/*` | Komponenty z prefixem `ad-` |\n| `~/composables/**` | Composables |\n\n## Stylowanie Komponentów\n\nDla komponentów Atomic Design zalecamy używanie **CSS Modules** - zapewniają automatyczne scopowanie, zapobiegają kolizjom nazw i świetnie współpracują z TypeScript.\n\n### Opcja 1: CSS Modules (Zalecane)\n\nUżyj atrybutu `module` na tagu style. Dostęp do klas przez obiekt `$style`:\n\n```html\n<template>\n  <div :class=\"$style['my-component']\">\n    <span :class=\"$style.label\">{{ label }}</span>\n  </div>\n</template>\n\n<style lang=\"scss\" module>\n.my-component {\n  display: flex;\n  padding: 1rem;\n\n  .label {\n    font-weight: 600;\n  }\n}\n</style>\n```\n\n**Zalety:**\n- Automatyczne unikalne nazwy klas (brak kolizji)\n- Wsparcie TypeScript przez `$style`\n- Lepsza enkapsulacja dla komponentów wielokrotnego użytku\n\n### Opcja 2: Normalne SCSS\n\nGlobalne style bez scopowania. Klasy używane bezpośrednio w template:\n\n```html\n<template>\n  <div class=\"my-component\">\n    <span class=\"label\">{{ label }}</span>\n  </div>\n</template>\n\n<style lang=\"scss\">\n.my-component {\n  display: flex;\n  padding: 1rem;\n\n  .label {\n    font-weight: 600;\n  }\n}\n</style>\n```\n\n**Kiedy używać:**\n- Globalne style i nadpisania\n- Style które muszą wpływać na komponenty potomne\n- Strony i layouty\n\n### Zewnętrzne Pliki SCSS\n\nDla złożonych komponentów, wyodrębnij style do `_index.scss`:\n\n```txt\nmy-component/\n├── _index.scss   # Style\n├── index.ts\n└── index.vue\n```\n\nZaimportuj w komponencie:\n\n```html\n<style lang=\"scss\">\n@import 'index';\n</style>\n```\n\n## Konwencje Nazewnictwa\n\n| Element | Konwencja | Przykład |\n|---------|-----------|----------|\n| Nazwy folderów | kebab-case | `my-component/` |\n| Eksporty komponentów | PascalCase z prefixem `Ad` | `AdMyComponent` |\n| Interfejsy | PascalCase z suffixem `Interface` | `MyComponentInterface` |\n| Klasy CSS | kebab-case | `.my-component` |\n| Pliki SCSS | prefix underscore | `_index.scss` |\n\n## Następne Kroki\n\n- Dowiedz się więcej o [Modułach](/pl/docs/core-concepts/modules) do organizacji funkcji\n- Poznaj metodologię [Atomic Design](/pl/docs/core-concepts/atomic-design)\n- Przeczytaj [Standardy Kodu](/pl/docs/contributing/code-standards) dla najlepszych praktyk\n\n",
  "pl/tests/vitest": "# Vitest (Testy Frontend)\n\nVitest to framework testowy frontend dla Vue/TypeScript w Nucleify.\n\n---\n\n## Konfiguracja\n\n### vitest.config.ts\n\n```typescript\nimport { defineVitestConfig } from '@nuxt/test-utils/config'\nimport { resolve } from 'path'\n\nexport default defineVitestConfig({\n  resolve: {\n    alias: {\n      nucleify: resolve(__dirname, 'nuxt/atomic'),\n    },\n  },\n  test: {\n    environment: 'nuxt',\n    setupFiles: ['./vitests/setup.ts'],\n    include: [\n      'vitests/**/*.{test,spec}.{js,ts,jsx,tsx}',\n      'modules/**/*.{test,spec}.{js,ts,jsx,tsx}',\n    ],\n    testTimeout: 30000,\n    pool: 'threads',\n  },\n})\n```\n\n---\n\n## Struktura\n\n### Testy globalne\n\n```\nvitests/\n├── setup.ts              # Globalny setup\n├── example.test.ts       # Przykładowy test\n└── plugins/              # Testy pluginów\n```\n\n### Testy modułów\n\n```\nmodules/nuc_example/vitests/\n├── api/\n│   └── User/\n│       └── 200.test.ts\n├── components/\n└── constants/\n    └── api/\n        ├── user.ts\n        └── article.ts\n```\n\n---\n\n## Plik Setup\n\n### vitests/setup.ts\n\n```typescript\nimport { afterEach } from 'vitest'\n\nconst activeTimeouts = new Set<NodeJS.Timeout>()\nconst activeIntervals = new Set<NodeJS.Timeout>()\n\nconst originalSetTimeout = globalThis.setTimeout\nconst trackedSetTimeout = (callback: Function, delay?: number) => {\n  const id = originalSetTimeout(() => {\n    activeTimeouts.delete(id)\n    callback()\n  }, delay)\n  activeTimeouts.add(id)\n  return id\n}\n\nglobalThis.setTimeout = trackedSetTimeout as typeof setTimeout\n\nafterEach(() => {\n  activeTimeouts.forEach((id) => clearTimeout(id))\n  activeTimeouts.clear()\n  activeIntervals.forEach((id) => clearInterval(id))\n  activeIntervals.clear()\n})\n```\n\n---\n\n## Mockowanie\n\n### mockGlobalFetch()\n\n```typescript\n// modules/nuc_api/utils/__mocks__/mock_global_fetch.ts\n\nimport type { Mock, vi } from 'vitest'\n\nexport function mockGlobalFetch(\n  vi: { fn: typeof vi.fn; stubGlobal: typeof vi.stubGlobal },\n  response: unknown\n): Mock {\n  const mockFetch: Mock = vi.fn().mockResolvedValue(response)\n  vi.stubGlobal('$fetch', mockFetch)\n  return mockFetch\n}\n```\n\n### Użycie\n\n```typescript\nimport { beforeEach, vi } from 'vitest'\nimport * as nucleify from 'nucleify'\n\nbeforeEach((): void => {\n  vi.clearAllMocks()\n  nucleify.mockGlobalFetch(vi, mockResponse)\n})\n```\n\n---\n\n## Dane mockowe\n\n```typescript\n// vitests/constants/api/user.ts\n\nimport type { NucUserObjectInterface } from 'nucleify'\n\nexport const mockUser: NucUserObjectInterface = {\n  id: 999999,\n  name: 'Test User',\n  email: 'test@example.com',\n  role: 'user',\n  created_at: new Date().toISOString(),\n  updated_at: new Date().toISOString(),\n}\n```\n\n---\n\n## Pisanie testów\n\n### Podstawowy test\n\n```typescript\nimport { expect, test } from 'vitest'\n\ntest('example', (): void => {\n  expect(true).toBe(true)\n})\n```\n\n### Testy requestów API\n\n```typescript\nimport { beforeEach, describe, expect, it, type Mock, vi } from 'vitest'\nimport * as nucleify from 'nucleify'\n\ndescribe('userRequests', (): void => {\n  const { closeDialog } = nucleify.useNucDialog()\n  const requests = nucleify.userRequests(closeDialog)\n  const mockResponse = [nucleify.mockUser]\n\n  beforeEach((): void => {\n    vi.clearAllMocks()\n    nucleify.mockGlobalFetch(vi, mockResponse)\n  })\n\n  it('getAllUsers', async (): Promise<void> => {\n    await requests.getAllUsers()\n    expect(\n      (globalThis as unknown as { $fetch: Mock }).$fetch\n    ).toHaveBeenCalledWith(\n      expect.stringContaining('users'),\n      expect.objectContaining({ method: 'GET' })\n    )\n    expect(requests.results.value).toEqual(mockResponse)\n  })\n\n  it('storeUser', async (): Promise<void> => {\n    await requests.storeUser(nucleify.mockUser)\n    expect(\n      (globalThis as unknown as { $fetch: Mock }).$fetch\n    ).toHaveBeenCalledWith(\n      expect.stringContaining('users'),\n      expect.objectContaining({ method: 'POST' })\n    )\n  })\n\n  it('deleteUser', async (): Promise<void> => {\n    await requests.deleteUser(nucleify.mockUser.id ?? 0)\n    expect(\n      (globalThis as unknown as { $fetch: Mock }).$fetch\n    ).toHaveBeenCalledWith(\n      expect.stringContaining('users'),\n      expect.objectContaining({ method: 'DELETE' })\n    )\n  })\n})\n```\n\n### Testy composables\n\n```typescript\nimport { beforeEach, describe, expect, it, vi } from 'vitest'\nimport * as nucleify from 'nucleify'\n\ndescribe('useAddFriend', (): void => {\n  let instance: ReturnType<typeof nucleify.useAddFriend>\n\n  beforeEach((): void => {\n    vi.clearAllMocks()\n    instance = nucleify.useAddFriend()\n  })\n\n  it('should add friend', async (): Promise<void> => {\n    nucleify.mockGlobalFetch(vi, [{ id: 1, name: 'Test' }])\n    const spy = vi.spyOn(friendship, 'sendRequest')\n\n    await instance.handleAddFriend()\n\n    expect(spy).toHaveBeenCalled()\n  })\n})\n```\n\n### Testowanie ze spy\n\n```typescript\nimport { describe, expect, it, vi } from 'vitest'\n\ndescribe('spies', (): void => {\n  it('should track calls', (): void => {\n    const callback = vi.fn()\n    callback('arg1', 'arg2')\n    \n    expect(callback).toHaveBeenCalledTimes(1)\n    expect(callback).toHaveBeenCalledWith('arg1', 'arg2')\n  })\n\n  it('should spy on methods', (): void => {\n    const obj = { method: (x: number) => x * 2 }\n    const spy = vi.spyOn(obj, 'method')\n    \n    obj.method(5)\n    \n    expect(spy).toHaveBeenCalledWith(5)\n    expect(spy).toHaveReturnedWith(10)\n  })\n})\n```\n\n---\n\n## Asercje\n\n### Powszechne matchery\n\n```typescript\n// Równość\nexpect(value).toBe(expected)\nexpect(value).toEqual(expected)\n\n// Prawdziwość\nexpect(value).toBeTruthy()\nexpect(value).toBeFalsy()\nexpect(value).toBeNull()\nexpect(value).toBeDefined()\n\n// Liczby\nexpect(value).toBeGreaterThan(3)\nexpect(value).toBeLessThan(5)\n\n// Stringi\nexpect(value).toMatch(/regex/)\nexpect(value).toContain('substring')\n\n// Tablice/Obiekty\nexpect(array).toContain(item)\nexpect(array).toHaveLength(3)\nexpect(obj).toHaveProperty('key')\n\n// Funkcje\nexpect(fn).toHaveBeenCalled()\nexpect(fn).toHaveBeenCalledWith(arg)\nexpect(fn).toHaveBeenCalledTimes(2)\n\n// Async\nawait expect(promise).resolves.toBe(value)\nawait expect(promise).rejects.toThrow(Error)\n\n// Częściowe dopasowanie\nexpect(obj).toMatchObject({ key: 'value' })\nexpect('test').stringContaining('est')\nexpect({ a: 1 }).objectContaining({ a: 1 })\n```\n\n---\n\n## Komendy\n\n```bash\n# Uruchom wszystkie testy\npnpm run tests\n\n# Tryb watch\npnpm run test:watch\n\n# Uruchom raz\npnpm run tests\n\n# Konkretny plik\npnpm exec vitest modules/nuc_entities/vitests/api/User/200.test.ts\n\n# Z wzorcem\npnpm exec vitest --filter=\"userRequests\"\n\n# Z coverage\npnpm run test:coverage\n\n# Z UI\npnpm exec vitest --ui\n\n# Aktualizuj snapshoty\npnpm exec vitest --update\n```\n\n---\n\n## Dobre praktyki\n\n1. **Używaj aliasu `nucleify`** - Importuj z `nuxt/atomic`\n2. **Mockuj global fetch** - `nucleify.mockGlobalFetch(vi, response)`\n3. **Czyść mocki** - `vi.clearAllMocks()` w `beforeEach`\n4. **Używaj bloków `describe`** - Grupuj powiązane testy\n5. **Trzymaj testy modułów** w `modules/*/vitests/`\n6. **Testuj async** z `async/await`\n7. **Używaj danych mockowych** - Stałe w `vitests/constants/`\n8. **Testuj CRUD** - GET, POST, PUT, DELETE\n9. **Używaj częściowych matcherów** - `stringContaining()`, `objectContaining()`\n",
}

export function getBundledMarkdown(lang: string, category: string, slug: string): string | null {
  return MARKDOWN_BUNDLE[`${lang}/${category}/${slug}`] ?? null
}
